1	import { Router, Response } from "express";
2	import bcrypt from "bcryptjs";
3	import db from "./db.js";
4	import { AuthRequest, authMiddleware, requireRole, signToken, setAuthCookie, clearAuthCookie } from "./auth.js";
5	import { runTopsisAllActive, calculateTopsisForDonation } from "./topsis.js";
6	import { validate, loginSchema, registerDonorSchema, registerRecipientSchema, registerAdminSchema, createDonationSchema, claimDonationSchema, reviewSchema, adminVerifySchema, emergencySchema } from "./validate.js";
7	
8	export const apiRouter = Router();
9	
10	// --- Auth ---
11	apiRouter.post("/auth/register/admin", validate(registerAdminSchema), async (req: AuthRequest, res: Response): Promise<void> => {
12	  const adminKey = process.env.ADMIN_SECRET_KEY || (process.env.NODE_ENV === "production" ? (() => { throw new Error("ADMIN_SECRET_KEY environment variable is required in production"); })() : "admin-secret-change-me");
13	  if (req.body.admin_key !== adminKey) {
14	    res.status(403).json({ message: "Kunci admin tidak valid" });
15	    return;
16	  }
17	  const { name, email, password } = req.body;
18	  if (!name || !email || !password) {
19	    res.status(400).json({ message: "Nama, email, dan password wajib diisi" });
20	    return;
21	  }
22	  const existing = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
23	  if (existing) {
24	    res.status(409).json({ message: "Email sudah terdaftar" });
25	    return;
26	  }
27	  const hash = await bcrypt.hash(password, 10);
28	  const result = db.prepare("INSERT INTO users (name, email, password, role, status) VALUES (?, ?, ?, 'admin', 'verified')").run(name, email, hash);
29	  const user = db.prepare("SELECT id, name, email, role, status FROM users WHERE id = ?").get(result.lastInsertRowid) as any;
30	  res.json({ message: "Admin berhasil dibuat", user });
31	});
32	
33	apiRouter.post("/auth/login", validate(loginSchema), async (req: AuthRequest, res: Response): Promise<void> => {
34	  const { email, password } = req.body;
35	  const user = db.prepare("SELECT * FROM users WHERE email = ?").get(email) as any;
36	  if (!user || !(await bcrypt.compare(password, user.password))) {
37	    res.status(401).json({ message: "Kredensial tidak valid" });
38	    return;
39	  }
40	  if (user.status !== "verified" && user.role !== "admin") {
41	    res.status(403).json({ message: "Akun Anda belum diverifikasi admin." });
42	    return;
43	  }
44	  let profile = null;
45	  if (user.role === "donor") profile = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(user.id);
46	  if (user.role === "recipient") profile = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(user.id);
47	
48	  const token = signToken(user);
49	  setAuthCookie(res, token);
50	
51	  const { password: _, ...safeUser } = user;
52	  res.json({ user: safeUser, profile });
53	});
54	
55	apiRouter.post("/auth/logout", (_req: AuthRequest, res: Response) => {
56	  clearAuthCookie(res);
57	  res.json({ message: "Logout berhasil" });
58	});
59	
60	apiRouter.get("/auth/me", authMiddleware, (req: AuthRequest, res: Response) => {
61	  const user = db.prepare("SELECT id, name, email, role, status FROM users WHERE id = ?").get(req.user!.id) as any;
62	  if (!user) { clearAuthCookie(res); res.status(401).json({ message: "User tidak ditemukan" }); return; }
63	  let profile = null;
64	  if (user.role === "donor") profile = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(user.id);
65	  if (user.role === "recipient") profile = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(user.id);
66	  res.json({ user, profile });
67	});
68	
69	// --- Registration ---
70	apiRouter.post("/auth/register/donor", validate(registerDonorSchema), async (req: AuthRequest, res: Response): Promise<void> => {
71	  const { business_name, email, password, business_type, address, latitude, longitude, phone } = req.body;
72	  const existing = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
73	  if (existing) { res.status(409).json({ message: "Email sudah terdaftar" }); return; }
74	  const hash = await bcrypt.hash(password, 10);
75	  const uResult = db.prepare("INSERT INTO users (name, email, password, role, status) VALUES (?, ?, ?, 'donor', 'pending')").run(business_name, email, hash);
76	  const userId = uResult.lastInsertRowid as number;
77	  db.prepare("INSERT INTO donor_profiles (user_id, business_name, business_type, address, latitude, longitude, phone) VALUES (?, ?, ?, ?, ?, ?, ?)")
78	    .run(userId, business_name, business_type, address, parseFloat(latitude), parseFloat(longitude), phone);
79	  res.json({ message: "Berhasil daftar. Menunggu verifikasi admin." });
80	});
81	
82	apiRouter.post("/auth/register/recipient", validate(registerRecipientSchema), async (req: AuthRequest, res: Response): Promise<void> => {
83	  const { institution_name, email, password, institution_type, address, latitude, longitude, phone, resident_count, age_range, health_condition, daily_protein_need, daily_calorie_need, daily_iron_need, daily_vitamin_c_need } = req.body;
84	  const existing = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
85	  if (existing) { res.status(409).json({ message: "Email sudah terdaftar" }); return; }
86	  const hash = await bcrypt.hash(password, 10);
87	  const uResult = db.prepare("INSERT INTO users (name, email, password, role, status) VALUES (?, ?, ?, 'recipient', 'pending')").run(institution_name, email, hash);
88	  const userId = uResult.lastInsertRowid as number;
89	  db.prepare(`INSERT INTO recipient_profiles (user_id, institution_name, institution_type, address, latitude, longitude, phone, resident_count, age_range, health_condition, daily_protein_need, daily_calorie_need, daily_iron_need, daily_vitamin_c_need) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
90	    .run(userId, institution_name, institution_type, address, parseFloat(latitude), parseFloat(longitude), phone, parseInt(resident_count), age_range, health_condition, parseFloat(daily_protein_need), parseFloat(daily_calorie_need), parseFloat(daily_iron_need), parseFloat(daily_vitamin_c_need));
91	  res.json({ message: "Berhasil daftar. Menunggu verifikasi admin." });
92	});
93	
94	// --- Profile ---
95	apiRouter.put("/users/:id/profile", authMiddleware, async (req: AuthRequest, res: Response): Promise<void> => {
96	  const userId = parseInt(req.params.id);
97	  const user = db.prepare("SELECT * FROM users WHERE id = ?").get(userId) as any;
98	  if (!user) { res.status(404).json({ message: "User tidak ditemukan" }); return; }
99	  const d = req.body;
100	  if (d.name) db.prepare("UPDATE users SET name = ? WHERE id = ?").run(d.name, userId);
101	  if (d.email) db.prepare("UPDATE users SET email = ? WHERE id = ?").run(d.email, userId);
102	  if (d.password) db.prepare("UPDATE users SET password = ? WHERE id = ?").run(await bcrypt.hash(d.password, 10), userId);
103	
104	  if (user.role === "donor") {
105	    const p = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(userId);
106	    if (p) {
107	      if (d.business_name) db.prepare("UPDATE donor_profiles SET business_name = ? WHERE user_id = ?").run(d.business_name, userId);
108	      if (d.business_type) db.prepare("UPDATE donor_profiles SET business_type = ? WHERE user_id = ?").run(d.business_type, userId);
109	      if (d.address) db.prepare("UPDATE donor_profiles SET address = ? WHERE user_id = ?").run(d.address, userId);
110	      if (d.latitude) db.prepare("UPDATE donor_profiles SET latitude = ? WHERE user_id = ?").run(parseFloat(d.latitude), userId);
111	      if (d.longitude) db.prepare("UPDATE donor_profiles SET longitude = ? WHERE user_id = ?").run(parseFloat(d.longitude), userId);
112	      if (d.phone) db.prepare("UPDATE donor_profiles SET phone = ? WHERE user_id = ?").run(d.phone, userId);
113	      if (d.logo_url !== undefined) db.prepare("UPDATE donor_profiles SET logo_url = ? WHERE user_id = ?").run(d.logo_url, userId);
114	    }
115	  } else if (user.role === "recipient") {
116	    const p = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(userId);
117	    if (p) {
118	      if (d.institution_name) db.prepare("UPDATE recipient_profiles SET institution_name = ? WHERE user_id = ?").run(d.institution_name, userId);
119	      if (d.institution_type) db.prepare("UPDATE recipient_profiles SET institution_type = ? WHERE user_id = ?").run(d.institution_type, userId);
120	      if (d.address) db.prepare("UPDATE recipient_profiles SET address = ? WHERE user_id = ?").run(d.address, userId);
121	      if (d.latitude) db.prepare("UPDATE recipient_profiles SET latitude = ? WHERE user_id = ?").run(parseFloat(d.latitude), userId);
122	      if (d.longitude) db.prepare("UPDATE recipient_profiles SET longitude = ? WHERE user_id = ?").run(parseFloat(d.longitude), userId);
123	      if (d.phone) db.prepare("UPDATE recipient_profiles SET phone = ? WHERE user_id = ?").run(d.phone, userId);
124	      if (d.logo_url !== undefined) db.prepare("UPDATE recipient_profiles SET document_url = ? WHERE user_id = ?").run(d.logo_url, userId);
125	      if (d.resident_count) db.prepare("UPDATE recipient_profiles SET resident_count = ? WHERE user_id = ?").run(parseInt(d.resident_count), userId);
126	      if (d.daily_protein_need) db.prepare("UPDATE recipient_profiles SET daily_protein_need = ? WHERE user_id = ?").run(parseFloat(d.daily_protein_need), userId);
127	      if (d.daily_calorie_need) db.prepare("UPDATE recipient_profiles SET daily_calorie_need = ? WHERE user_id = ?").run(parseFloat(d.daily_calorie_need), userId);
128	      if (d.daily_iron_need) db.prepare("UPDATE recipient_profiles SET daily_iron_need = ? WHERE user_id = ?").run(parseFloat(d.daily_iron_need), userId);
129	      if (d.daily_vitamin_c_need) db.prepare("UPDATE recipient_profiles SET daily_vitamin_c_need = ? WHERE user_id = ?").run(parseFloat(d.daily_vitamin_c_need), userId);
130	    }
131	  }
132	  const updated = db.prepare("SELECT id, name, email, role, status FROM users WHERE id = ?").get(userId) as any;
133	  let profile = null;
134	  if (user.role === "donor") profile = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(userId);
135	  if (user.role === "recipient") profile = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(userId);
136	  res.json({ message: "Profil berhasil diperbarui", user: updated, profile });
137	});
138	
139	// --- Public Data ---
140	apiRouter.get("/public/top-donors", (_req: AuthRequest, res: Response) => {
141	  const donors = db.prepare("SELECT * FROM donor_profiles ORDER BY total_donations DESC LIMIT 3").all() as any[];
142	  const result = donors.map((p: any) => {
143	    const reviews = db.prepare("SELECT rating FROM reviews WHERE donor_id = ?").all(p.user_id) as any[];
144	    const avgRating = reviews.length > 0 ? reviews.reduce((sum: number, r: any) => sum + r.rating, 0) / reviews.length : 0;
145	    return {
146	      id: p.user_id, business_name: p.business_name, total_donations: p.total_donations,
147	      type: p.business_type, logo_url: p.logo_url,
148	      rating: avgRating.toFixed(1), review_count: reviews.length
149	    };
150	  });
151	  res.json(result);
152	});
153	
154	// --- Dashboard Stats ---
155	apiRouter.get("/dashboard/stats", (_req: AuthRequest, res: Response) => {
156	  const donors = (db.prepare("SELECT COUNT(*) as c FROM users WHERE role = 'donor'").get() as any).c;
157	  const recipients = (db.prepare("SELECT COUNT(*) as c FROM users WHERE role = 'recipient'").get() as any).c;
158	  const active = (db.prepare("SELECT COUNT(*) as c FROM donations WHERE status = 'active'").get() as any).c;
159	  const completed = (db.prepare("SELECT COUNT(*) as c FROM donations WHERE status = 'completed'").get() as any).c;
160	  res.json({ donors, recipients, active_donations: active, completed_donations: completed });
161	});
162	
163	// --- Donations ---
164	apiRouter.post("/donations", authMiddleware, requireRole("donor"), validate(createDonationSchema), (req: AuthRequest, res: Response) => {
165	  const d = req.body;
166	  const result = db.prepare(`INSERT INTO donations (donor_id, food_name, food_type, portion_count, protein_per_portion, calorie_per_portion, iron_mg, vitamin_c_mg, valid_until, pickup_latitude, pickup_longitude, notes, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
167	    .run(req.user!.id, d.food_name, d.food_type, parseInt(d.portion_count), parseFloat(d.protein_per_portion), parseFloat(d.calorie_per_portion), d.iron_mg ? parseFloat(d.iron_mg) : null, d.vitamin_c_mg ? parseFloat(d.vitamin_c_mg) : null, new Date(Date.now() + parseInt(d.hours_valid) * 3600000).toISOString(), parseFloat(d.pickup_latitude), parseFloat(d.pickup_longitude), d.notes, new Date().toISOString());
168	  const donId = result.lastInsertRowid as number;
169	  calculateTopsisForDonation(donId);
170	  res.json({ message: "Donasi berhasil dipublikasikan!" });
171	});
172	
173	apiRouter.get("/donations", (req: AuthRequest, res: Response) => {
174	  const donorId = req.query.donor_id;
175	  const page = Math.max(1, parseInt(req.query.page as string) || 1);
176	  const limit = Math.min(100, Math.max(1, parseInt(req.query.limit as string) || 20));
177	  const offset = (page - 1) * limit;
178	  let donations: any[];
179	  if (donorId) {
180	    donations = db.prepare("SELECT * FROM donations WHERE donor_id = ? ORDER BY id DESC LIMIT ? OFFSET ?").all(parseInt(donorId as string), limit, offset);
181	  } else {
182	    donations = db.prepare("SELECT * FROM donations ORDER BY id DESC LIMIT ? OFFSET ?").all(limit, offset);
183	  }
184	  const enriched = donations.map((d: any) => {
185	    let recipient_info = null;
186	    if (d.claimed_by) {
187	      const r = db.prepare("SELECT institution_name, latitude, longitude FROM recipient_profiles WHERE user_id = ?").get(d.claimed_by) as any;
188	      if (r) recipient_info = { name: r.institution_name, lat: r.latitude, lon: r.longitude };
189	    }
190	    return { ...d, recipient_info };
191	  });
192	  res.json(enriched);
193	});
194	
195	apiRouter.get("/donations/transit", authMiddleware, (req: AuthRequest, res: Response) => {
196	  const userId = parseInt(req.query.user_id as string);
197	  const role = req.query.role as string;
198	  let inTransit: any[];
199	  if (role === "recipient") {
200	    inTransit = db.prepare("SELECT * FROM donations WHERE claimed_by = ? AND status = 'claimed'").all(userId);
201	  } else {
202	    inTransit = db.prepare("SELECT * FROM donations WHERE donor_id = ? AND status = 'claimed'").all(userId);
203	  }
204	  const enriched = inTransit.map((d: any) => {
205	    const dProf = db.prepare("SELECT business_name FROM donor_profiles WHERE user_id = ?").get(d.donor_id) as any;
206	    const rProf = db.prepare("SELECT institution_name, latitude, longitude FROM recipient_profiles WHERE user_id = ?").get(d.claimed_by) as any;
207	    return {
208	      ...d, donor_name: dProf?.business_name, donor_lat: d.pickup_latitude, donor_lon: d.pickup_longitude,
209	      recipient_name: rProf?.institution_name, recipient_lat: rProf?.latitude, recipient_lon: rProf?.longitude
210	    };
211	  });
212	  res.json(enriched);
213	});
214	
215	apiRouter.get("/donations/active", (req: AuthRequest, res: Response) => {
216	  const recipient_id = parseInt(req.query.recipient_id as string);
217	  const active = db.prepare("SELECT * FROM donations WHERE status = 'active'").all() as any[];
218	  const enriched = active.map((d: any) => {
219	    const topsis = db.prepare("SELECT rank_position, ci_score FROM topsis_results WHERE donation_id = ? AND recipient_id = ?").get(d.id, recipient_id) as any;
220	    const dProf = db.prepare("SELECT business_name, address FROM donor_profiles WHERE user_id = ?").get(d.donor_id) as any;
221	    const claim = db.prepare("SELECT status FROM claims WHERE donation_id = ? AND recipient_id = ?").get(d.id, recipient_id) as any;
222	    return {
223	      ...d, rank: topsis?.rank_position || null, ci_score: topsis?.ci_score || null,
224	      donor_name: dProf?.business_name, donor_address: dProf?.address, my_claim_status: claim?.status || null
225	    };
226	  });
227	  enriched.sort((a: any, b: any) => (a.rank || 999) - (b.rank || 999));
228	  res.json(enriched);
229	});
230	
