               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
               <div>
                  <label htmlFor="recip-iron" className="block text-gray-700 font-medium mb-1">Kebutuhan Zat Besi Harian (mg)</label>
                  <input id="recip-iron" placeholder="Estimasi(mg)" type="number" value={form.daily_iron_need} onChange={e=>setForm({...form, daily_iron_need: e.target.value})} className="w-full border border-gray-200 p-3.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#1565C0] focus:border-transparent transition-all outline-none" />
               </div>
               <div>
                  <label htmlFor="recip-vitaminc" className="block text-gray-700 font-medium mb-1">Kebutuhan Vitamin C Harian (mg)</label>
                  <input id="recip-vitaminc" placeholder="Estimasi(mg)" type="number" value={form.daily_vitamin_c_need} onChange={e=>setForm({...form, daily_vitamin_c_need: e.target.value})} className="w-full border border-gray-200 p-3.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#1565C0] focus:border-transparent transition-all outline-none" />
