          </form>
          <div className="mt-8 text-center border-t border-gray-100 pt-6">
            <span className="text-gray-500">Sudah punya akun? </span>
            <Link to="/login" className="text-[#1565C0] font-bold hover:underline">Masuk di sini.</Link>
          </div>
        </motion.div>
      </div>
    </div>
  )
}

