                Donasi Pangan
              </Link>
              <Link to="/register/recipient" className="px-4 py-2 text-sm font-medium bg-white text-[#2D7A4F] border border-[#2D7A4F] rounded-full hover:bg-gray-50 transition-all hidden lg:inline-block">
