            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] bg-black/40 md:hidden"
            onClick={() => setMobileOpen(false)}
          >
            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 200 }}
              className="absolute right-0 top-0 bottom-0 w-72 bg-white shadow-2xl p-6"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex justify-between items-center mb-8">
                <span className="font-bold text-[#2D7A4F] flex items-center gap-2">
                  <Heart className="fill-current text-[#52C77F]" size={20} />
                  NUTRI-SHARE
                </span>
                <button onClick={() => setMobileOpen(false)} className="p-2 text-gray-500">
                  <X size={24} />
                </button>
              </div>
              <div className="flex flex-col gap-4">
                <a href="#tentang" onClick={() => setMobileOpen(false)} className="py-3 border-b border-gray-100 font-medium">Tentang</a>
                <a href="#cara-kerja" onClick={() => setMobileOpen(false)} className="py-3 border-b border-gray-100 font-medium">Cara Kerja</a>
                <a href="#dampak" onClick={() => setMobileOpen(false)} className="py-3 border-b border-gray-100 font-medium">Dampak</a>
                {topDonors.length > 0 && (
                  <a href="#pahlawan" onClick={() => setMobileOpen(false)} className="py-3 border-b border-gray-100 font-medium">Pahlawan Pangan</a>
                )}
                <div className="mt-6 flex flex-col gap-3">
                  <Link to="/login" onClick={() => setMobileOpen(false)} className="text-center py-3 border border-gray-300 rounded-full font-medium">Masuk</Link>
                  <Link to="/register/donor" onClick={() => setMobileOpen(false)} className="text-center py-3 bg-[#2D7A4F] text-white rounded-full font-medium">Donasi Pangan</Link>
                  <Link to="/register/recipient" onClick={() => setMobileOpen(false)} className="text-center py-3 bg-white text-[#2D7A4F] border border-[#2D7A4F] rounded-full font-medium">Daftar Penerima</Link>
