import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { api } from "../lib/api";
import { Donation } from "../types";
import { useAuth } from "../contexts/AuthContext";
import { LiveTrackingModal } from "../components/LiveTrackingModal";
import { ProfileModal } from "../components/ProfileModal";
import { EmptyState } from "../components/EmptyState";
import { LoadingSpinner } from "../components/LoadingSpinner";
import {
  Star, Package, Clock, Plus, Filter,
  ListFilter, Activity, CheckCircle, Truck
} from "lucide-react";
import toast from "react-hot-toast";
import { formatDistanceToNow } from "date-fns";
import { id as idLocale } from "date-fns/locale";
import { motion } from "motion/react";

type FilterTab = "all" | "active" | "claimed" | "completed";

export function DonorDashboard() {
  const [donations, setDonations] = useState<Donation[]>([]);
  const [trackingData, setTrackingData] = useState<any>(null);
  const [showProfile, setShowProfile] = useState(false);
  const [reviews, setReviews] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [filterTab, setFilterTab] = useState<FilterTab>("all");
  const [showForm, setShowForm] = useState(false);
  const nav = useNavigate();
  const { user, profile, loading: authLoading, logout, refresh } = useAuth();

  const [form, setForm] = useState({
    food_name: "", food_type: "makanan_berat", portion_count: "", protein_per_portion: "",
    calorie_per_portion: "", hours_valid: "6", pickup_latitude: 0, pickup_longitude: 0,
    notes: "", iron_mg: "", vitamin_c_mg: ""
  });

  useEffect(() => {
    if (profile) {
      setForm(f => ({ ...f, pickup_latitude: profile.latitude, pickup_longitude: profile.longitude }));
    }
  }, [profile]);

  useEffect(() => {
    if (!authLoading && (!user || user.role !== "donor")) nav("/login");
  }, [authLoading, user]);

  if (authLoading || !user) return null;

  const loadDonations = async () => {
    try {
      const data = await api.fetchJSON(`/api/donations?donor_id=${user.id}`);
      setDonations(data);
      const donorReviews = await api.fetchJSON(`/api/donors/${user.id}/reviews`);
      setReviews(donorReviews);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadDonations(); }, []);

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    try {
      await api.fetchJSON("/api/donations", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ...form, donor_id: user.id })
      });
      toast.success("Donasi berhasil dipublikasikan!");
      loadDonations();
      setForm({
        ...form, food_name: "", portion_count: "", protein_per_portion: "",
        calorie_per_portion: "", iron_mg: "", vitamin_c_mg: ""
      });
      setShowForm(false);
    } catch (err: any) { toast.error(err.message || "Gagal mencatat donasi"); }
  };

  const handleComplete = async (donationId: number) => {
    try {
      await api.fetchJSON(`/api/donations/${donationId}/complete`, { method: "POST" });
      toast.success("Donasi berhasil diselesaikan!");
      loadDonations();
    } catch (err: any) { toast.error(err.message || "Gagal menyelesaikan donasi"); }
  };

  const filtered = donations.filter(d => {
    if (filterTab === "active") return d.status === "active";
    if (filterTab === "claimed") return d.status === "claimed";
    if (filterTab === "completed") return d.status === "completed";
    return true;
  });

  const statusCount = (status: string) => donations.filter(d => d.status === status).length;

  const statusBadge = (status: string, arrived?: boolean) => {
    const styles: Record<string, string> = {
      active: "bg-[#E8F5E9] text-[#2D7A4F] border border-[#52C77F]/30",
      claimed: arrived
        ? "bg-[#FFF3E0] text-[#E65100] border border-[#FFB74D]/30"
        : "bg-[#E3F2FD] text-[#1565C0] border border-[#90CAF9]/30",
      completed: "bg-gray-100 text-gray-600 border border-gray-200",
      expired: "bg-red-50 text-red-500 border border-red-200",
    };
    const labels: Record<string, string> = {
      active: "AKTIF",
      claimed: arrived ? "KURIR SAMPAI" : "DIKLAIM",
      completed: "SELESAI",
      expired: "KADALUARSA",
    };
    return (
      <span className={`px-3 py-1 rounded-full text-xs font-bold inline-flex items-center gap-1 ${styles[status] || styles.active}`}>
        {status === "active" && <Activity size={12} />}
        {status === "claimed" && <Truck size={12} />}
        {status === "completed" && <CheckCircle size={12} />}
        {labels[status] || status.toUpperCase()}
      </span>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#F7F4EE] p-6">
        <LoadingSpinner size={32} label="Memuat dashboard..." />
      </div>
    );
  }

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="min-h-screen bg-[#F7F4EE] p-6 text-[#2C2C2C]">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <header className="flex justify-between items-center bg-white p-6 rounded-2xl shadow-sm mb-6">
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-2xl font-bold text-[#2D7A4F]">Dashboard Donor</h1>
              <span className="bg-[#E8F5E9] text-[#2D7A4F] text-xs font-bold px-3 py-1 rounded-full border border-[#52C77F]/30">
                {donations.length} Donasi
              </span>
            </div>
            <p className="text-gray-500 flex items-center gap-2 mt-1">
              {profile.business_name} - {profile.business_type}
              {reviews.length > 0 && (
                <span className="flex items-center gap-1 text-[#F5A623] bg-[#FFF8E1] px-2 py-0.5 rounded-full text-xs font-bold border border-[#FFECB3]">
                  <Star size={12} fill="currentColor" />
                  {(reviews.reduce((a, b) => a + b.rating, 0) / reviews.length).toFixed(1)} ({reviews.length} ulasan)
                </span>
              )}
            </p>
          </div>
          <div className="flex gap-4 items-center">
            <button onClick={() => setShowProfile(true)} className="text-sm font-medium hover:text-[#2D7A4F] bg-gray-50 px-4 py-2 rounded-xl border">Profil Saya</button>
            <button onClick={async () => { await logout(); nav("/"); }} className="text-sm font-medium hover:text-[#E53935]">Logout</button>
          </div>
        </header>

        <div className="grid md:grid-cols-3 gap-6">
          {/* Form Column */}
          <div className="md:col-span-1">
            <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="bg-white p-6 rounded-2xl shadow-sm h-fit">
              <button
                onClick={() => setShowForm(!showForm)}
                className="w-full flex items-center justify-between text-lg font-bold mb-1"
              >
                <span className="flex items-center gap-2"><Plus size={20} className="text-[#2D7A4F]" /> Input Surplus Pangan</span>
                <motion.span animate={{ rotate: showForm ? 45 : 0 }} className="text-[#2D7A4F]"><Plus size={20} /></motion.span>
              </button>
              <p className="text-xs text-gray-400 mb-4">Publikasikan makanan surplus Anda untuk didistribusikan</p>

              <motion.div
                initial={false}
                animate={{ height: showForm ? "auto" : 0, opacity: showForm ? 1 : 0 }}
                className="overflow-hidden"
              >
                <form onSubmit={handleSubmit} className="flex flex-col gap-4 text-sm pt-2 border-t">
                  <div>
                    <label className="text-xs font-bold text-gray-600 mb-1 block">Nama Makanan</label>
                    <input aria-label="Nama Makanan" placeholder="Ex: Nasi Kotak" value={form.food_name}
                      onChange={e => setForm({ ...form, food_name: e.target.value })}
                      className="w-full border border-gray-200 p-2.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none" required />
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs font-bold text-gray-600 mb-1 block">Jumlah Porsi</label>
                      <input aria-label="Jumlah Porsi" type="number" placeholder="Porsi" value={form.portion_count}
                        onChange={e => setForm({ ...form, portion_count: e.target.value })}
                        className="w-full border border-gray-200 p-2.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none" required />
                    </div>
                    <div>
                      <label className="text-xs font-bold text-gray-600 mb-1 block">Masa Layak</label>
                      <input aria-label="Masa Layak dalam Jam" type="number" placeholder="Jam" value={form.hours_valid}
                        onChange={e => setForm({ ...form, hours_valid: e.target.value })}
                        className="w-full border border-gray-200 p-2.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none" required />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs font-bold text-gray-600 mb-1 block">Protein/porsi (g)</label>
                      <input aria-label="Protein per Porsi dalam Gram" type="number" placeholder="Protein" value={form.protein_per_portion}
                        onChange={e => setForm({ ...form, protein_per_portion: e.target.value })}
                        className="w-full border border-gray-200 p-2.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none" required />
                    </div>
                    <div>
                      <label className="text-xs font-bold text-gray-600 mb-1 block">Kalori/porsi</label>
                      <input aria-label="Kalori per Porsi" type="number" placeholder="Kalori" value={form.calorie_per_portion}
                        onChange={e => setForm({ ...form, calorie_per_portion: e.target.value })}
                        className="w-full border border-gray-200 p-2.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none" required />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs font-bold text-gray-600 mb-1 block">Zat Besi (mg) <span className="text-gray-400 font-normal">opsional</span></label>
                      <input aria-label="Zat Besi dalam Miligram (Opsional)" type="number" placeholder="Fe" value={form.iron_mg}
                        onChange={e => setForm({ ...form, iron_mg: e.target.value })}
                        className="w-full border border-gray-200 p-2.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none" />
                    </div>
                    <div>
                      <label className="text-xs font-bold text-gray-600 mb-1 block">Vitamin C (mg) <span className="text-gray-400 font-normal">opsional</span></label>
                      <input aria-label="Vitamin C dalam Miligram (Opsional)" type="number" placeholder="Vit C" value={form.vitamin_c_mg}
                        onChange={e => setForm({ ...form, vitamin_c_mg: e.target.value })}
                        className="w-full border border-gray-200 p-2.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none" />
                    </div>
                  </div>
                  <button className="bg-[#2D7A4F] text-white py-3 rounded-xl font-bold mt-2 hover:bg-opacity-90 transform hover:-translate-y-0.5 transition-all shadow-md active:scale-95">
                    Publikasi Donasi
                  </button>
                </form>
              </motion.div>
            </motion.div>
          </div>

          {/* Donations List */}
          <div className="md:col-span-2 flex flex-col gap-4">
            {/* Filter Tabs */}
            <div className="flex items-center gap-2 mb-2 overflow-x-auto">
              {([["all", "Semua"], ["active", "Aktif"], ["claimed", "Dalam Perjalanan"], ["completed", "Selesai"]] as const).map(([key, label]) => (
                <button
                  key={key}
                  onClick={() => setFilterTab(key)}
                  className={`flex items-center gap-1.5 px-4 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${
                    filterTab === key
                      ? "bg-[#2D7A4F] text-white shadow-sm"
                      : "bg-white text-gray-600 border border-gray-200 hover:border-[#2D7A4F] hover:text-[#2D7A4F]"
                  }`}
                >
                  <ListFilter size={14} />
                  {label}
                  {key !== "all" && (
                    <span className={`text-xs ml-1 ${filterTab === key ? "text-white/80" : "text-gray-400"}`}>
                      ({statusCount(key === "claimed" ? "claimed" : key)})
                    </span>
                  )}
                </button>
              ))}
            </div>

            <div className="grid gap-4">
              {filtered.map((d, i) => (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.05 }}
                  key={d.id}
                  className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 flex flex-col sm:flex-row justify-between sm:items-center gap-4 hover:shadow-md transition-shadow"
                >
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-3 mb-1">
                      <h3 className="font-bold text-lg truncate">{d.food_name}</h3>
                      {statusBadge(d.status, (d as any).arrived_at)}
                    </div>
                    <p className="text-sm text-gray-500 flex items-center gap-2 mt-1">
                      <span className="flex items-center gap-1"><Package size={14} /> {d.portion_count} Porsi</span>
                      <span className="text-gray-300">•</span>
                      <span className="flex items-center gap-1"><Clock size={14} /> {new Date(d.valid_until).toLocaleString('id-ID', { hour: '2-digit', minute: '2-digit', day: 'numeric', month: 'short' })}</span>
                    </p>
                  </div>
                  <div className="flex sm:flex-col items-center sm:items-end gap-2 justify-between w-full sm:w-auto shrink-0">
                    <div className="flex gap-2">
                      {(d.status === 'claimed' || (d as any).arrived_at) && (
                        <button
                          onClick={() => setTrackingData({
                            ...d,
                            donor_lat: d.pickup_latitude,
                            donor_lon: d.pickup_longitude,
                            donor_name: profile.business_name,
                            recipient_lat: (d as any).recipient_info?.lat,
                            recipient_lon: (d as any).recipient_info?.lon,
                            recipient_name: (d as any).recipient_info?.name
                          })}
                          className="text-xs border border-gray-300 text-gray-700 bg-white px-3 py-1.5 rounded-lg font-bold hover:bg-gray-50 flex items-center gap-1"
                        >
                          Lacak Live
                        </button>
                      )}
                      {d.status === 'claimed' && (
                        <button
                          onClick={() => handleComplete(d.id)}
                          className="text-xs bg-[#2D7A4F] text-white px-3 py-1.5 rounded-lg font-bold hover:bg-opacity-90"
                        >
                          Selesai
                        </button>
                      )}
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            {filtered.length === 0 && (
              <EmptyState
                icon={<Package size={40} />}
                title={filterTab === "all" ? "Belum Ada Donasi" : "Tidak Ada Donasi"}
                description={
                  filterTab === "all"
                    ? "Mulai kurangi food waste dengan menambahkan donasi pertama Anda hari ini."
                    : `Tidak ada donasi dengan status ${filterTab} saat ini.`
                }
              />
            )}

            {/* Reviews */}
            {reviews.length > 0 && (
              <div className="mt-8">
                <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
                  <Star className="text-[#F5A623]" size={20} /> Ulasan Penerima
                </h2>
                <div className="grid md:grid-cols-2 gap-4">
                  {reviews.slice(0, 4).map((r: any) => (
                    <motion.div
                      initial={{ opacity: 0, scale: 0.95 }}
                      animate={{ opacity: 1, scale: 1 }}
                      key={r.id}
                      className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow"
                    >
                      <div className="flex justify-between items-start mb-2">
                        <span className="font-bold text-sm text-[#1565C0]">{r.recipient_name}</span>
                        <div className="flex items-center text-[#F5A623]">
                          {[...Array(5)].map((_, i) => (
                            <Star key={i} size={14} fill={i < r.rating ? "currentColor" : "none"} className={i < r.rating ? "" : "text-gray-300"} />
                          ))}
                        </div>
                      </div>
                      {r.comment && <p className="text-sm text-gray-600 italic">"{r.comment}"</p>}
                      <p className="text-xs text-gray-400 mt-2">{formatDistanceToNow(new Date(r.created_at), { addSuffix: true, locale: idLocale })}</p>
                    </motion.div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {trackingData && (
        <LiveTrackingModal donation={trackingData} user={user} onClose={() => setTrackingData(null)} onComplete={loadDonations} />
      )}

      {showProfile && (
        <ProfileModal
          user={user}
          profile={profile}
          onClose={() => setShowProfile(false)}
          onUpdate={() => refresh()}
        />
      )}
    </motion.div>
  );
}

