import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { api } from "../lib/api";
import { Claim } from "../types";
import { useAuth } from "../contexts/AuthContext";
import { ProfileModal } from "../components/ProfileModal";
import { EmptyState } from "../components/EmptyState";
import { ConfirmDialog } from "../components/ConfirmDialog";
import { LoadingSpinner } from "../components/LoadingSpinner";
import { motion } from "motion/react";
import toast from "react-hot-toast";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement
} from "chart.js";
import { Bar, Pie } from "react-chartjs-2";
import {
  Users, FileCheck, CheckCircle, Package, Mail, Building2, Trash2,
  UserCheck, AlertTriangle, TrendingUp, Activity
} from "lucide-react";

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement);

export function AdminDashboard() {
  const [users, setUsers] = useState<{ donors: any[], recipients: any[] }>({ donors: [], recipients: [] });
  const [claims, setClaims] = useState<Claim[]>([]);
  const [stats, setStats] = useState<any>({});
  const [showProfile, setShowProfile] = useState(false);
  const [search, setSearch] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<{ id: number; name: string } | null>(null);
  const nav = useNavigate();
  const { user: currentUser, profile, loading: authLoading, logout, refresh } = useAuth();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!authLoading && (!currentUser || currentUser.role !== "admin")) nav("/login");
  }, [authLoading, currentUser]);

  if (authLoading || !currentUser) return null;

  const loadData = async () => {
    try {
      const usr = await api.fetchJSON("/api/admin/users");
      setUsers(usr);
      const clm = await api.fetchJSON("/api/admin/claims");
      setClaims(clm);
      const st = await api.fetchJSON("/api/dashboard/stats");
      setStats(st);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadData(); }, []);

  const handleVerify = async (userId: number, urgencyScore?: number) => {
    const body = urgencyScore ? { urgency_score: urgencyScore } : {};
    try {
      await api.fetchJSON(`/api/admin/users/${userId}/verify`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body)
      });
      toast.success("User berhasil diverifikasi");
      loadData();
    } catch (err: any) { toast.error(err.message || "Gagal verifikasi"); }
  };

  const handleEmergencyToggle = async (userId: number) => {
    try {
      const res = await api.fetchJSON(`/api/admin/users/${userId}/emergency`, { method: "POST" });
      const msgs: Record<string, string> = {
        active: "Status darurat AKTIF (prioritas TOPSIS dinaikkan)",
        pending: "Permintaan darurat diajukan",
        none: "Status darurat NONAKTIF"
      };
      toast.success(msgs[res.emergency as string] || "Status darurat berubah");
      loadData();
    } catch (err: any) { toast.error(err.message || "Gagal mengubah status darurat"); }
  };

  const handleApproveClaim = async (claimId: number) => {
    try {
      await api.fetchJSON(`/api/admin/claims/${claimId}/approve`, { method: "POST" });
      toast.success("Klaim disetujui, donasi berpindah status untuk diserahkan ke penerima");
      loadData();
    } catch (err: any) { toast.error(err.message || "Gagal menyetujui klaim"); }
  };

  const handleDeleteUser = async () => {
    if (!deleteTarget) return;
    try {
      await api.fetchJSON(`/api/admin/users/${deleteTarget.id}`, { method: "DELETE" });
      toast.success(`User berhasil dihapus`);
      setDeleteTarget(null);
      loadData();
    } catch (err: any) { toast.error(err.message || "Gagal menghapus user"); }
  };

  const chartData = {
    labels: users.donors.slice(0, 5).map(d => d.business_name || d.name),
    datasets: [
      {
        label: 'Total Donasi Pangan',
        data: users.donors.slice(0, 5).map(d => d.total_donations || 0),
        backgroundColor: ['#2D7A4F', '#52C77F', '#81C784', '#A5D6A7', '#C8E6C9'],
        borderRadius: 6,
      }
    ]
  };

  const pieData = {
    labels: ['Panti Asuhan', 'Rumah Singgah', 'Lainnya'],
    datasets: [
      {
        label: 'Sebaran Penerima',
        data: [
          users.recipients.filter(x => x.institution_type === 'panti_asuhan').length,
          users.recipients.filter(x => x.institution_type === 'rumah_singgah').length,
          users.recipients.filter(x => x.institution_type === 'lainnya' || x.institution_type === 'lembaga_sosial').length,
        ],
        backgroundColor: ['#1565C0', '#E53935', '#F5A623'],
      }
    ]
  };

  const statCards = [
    { label: "Donor", value: stats.donors || 0, color: "text-[#2D7A4F]", bg: "bg-[#E8F5E9]", icon: Building2 },
    { label: "Penerima", value: stats.recipients || 0, color: "text-[#1565C0]", bg: "bg-[#E3F2FD]", icon: Users },
    { label: "Donasi Aktif", value: stats.active_donations || 0, color: "text-[#F5A623]", bg: "bg-[#FFF8E1]", icon: Activity },
    { label: "Selesai", value: stats.completed_donations || 0, color: "text-gray-700", bg: "bg-gray-100", icon: CheckCircle },
  ];

  if (loading) {
    return (
      <div className="min-h-screen bg-[#F7F4EE] p-6">
        <LoadingSpinner size={32} label="Memuat dashboard admin..." />
      </div>
    );
  }

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="min-h-screen bg-[#F7F4EE] p-6 text-[#2C2C2C]">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <header className="flex justify-between items-center bg-white p-6 rounded-2xl shadow-sm mb-6 border-l-4 border-gray-800">
          <div>
            <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-gray-900 to-gray-600">Admin Command Center</h1>
            <p className="text-gray-500">Otorisasi & Pemantauan Sistem NUTRI-SHARE</p>
          </div>
          <div className="flex gap-4 items-center">
            <button onClick={() => setShowProfile(true)} className="text-sm font-medium hover:text-[#2D7A4F] bg-gray-50 px-4 py-2 rounded-xl border">Profil Saya</button>
            <button onClick={async () => { await logout(); nav("/"); }} className="text-sm font-medium hover:text-[#E53935]">Logout</button>
          </div>
        </header>

        {/* Stat Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
          {statCards.map((item, i) => (
            <motion.div
              key={item.label}
              initial={{ y: 20, opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              transition={{ delay: 0.1 * i }}
              className="bg-white p-5 rounded-xl shadow-sm border hover:shadow-md transition-shadow"
            >
              <div className="flex items-center gap-3">
                <div className={`p-3 rounded-xl ${item.bg}`}>
                  <item.icon size={20} className={item.color} />
                </div>
                <div>
                  <div className={`text-2xl font-bold ${item.color}`}>{item.value}</div>
                  <div className="text-xs text-gray-500">{item.label}</div>
                </div>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Charts */}
        <div className="grid md:grid-cols-2 gap-6 mb-8">
          <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h2 className="text-lg font-bold mb-4">Top Donor Aktif</h2>
            {users.donors.length > 0 ? (
              <Bar data={chartData} options={{ responsive: true, plugins: { legend: { display: false } } }} />
            ) : (
              <div className="h-48 flex items-center justify-center text-gray-400">Belum ada data</div>
            )}
          </motion.div>
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="bg-white p-6 rounded-2xl shadow-sm border px-12">
            <h2 className="text-lg font-bold mb-4 text-center">Distribusi Jenis Lembaga</h2>
            {users.recipients.length > 0 ? (
              <Pie data={pieData} options={{ responsive: true, plugins: { legend: { position: 'bottom' } } }} />
            ) : (
              <div className="h-48 flex items-center justify-center text-gray-400">Belum ada data</div>
            )}
          </motion.div>
        </div>

        {/* Verification & Claims */}
        <div className="grid md:grid-cols-2 gap-6 pb-12">
          {/* USER VERIFICATION */}
          <div className="flex flex-col gap-4">
            <h2 className="text-lg font-bold flex items-center gap-2"><UserCheck size={20} /> Verifikasi Penerima Sosial</h2>
            {users.recipients.filter(u => u.status === "pending").map((u, i) => (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }} key={u.id} className="bg-white p-4 rounded-xl border flex flex-col gap-3 shadow-sm hover:shadow-md transition-shadow">
                <div>
                  <h3 className="font-bold">{u.institution_name}</h3>
                  <p className="text-xs text-gray-500">{u.email} • {u.address}</p>
                </div>
                <div className="flex items-center gap-2">
                  <label className="text-sm font-bold">Skor Urgensi(1-5):</label>
                  <select id={`urgency-${u.id}`} className="border rounded p-1 text-sm bg-gray-50 focus:ring-2 focus:ring-[#2D7A4F] outline-none" defaultValue="3">
                    <option value="1">1 - Standar</option>
                    <option value="2">2 - Rentan</option>
                    <option value="3">3 - Perhatian</option>
                    <option value="4">4 - Tinggi</option>
                    <option value="5">5 - Kritis</option>
                  </select>
                  <button onClick={() => {
                    const el = document.getElementById(`urgency-${u.id}`) as HTMLSelectElement;
                    handleVerify(u.id, parseInt(el.value));
                  }} className="ml-auto bg-[#2D7A4F] text-white px-4 py-1.5 rounded-lg text-sm font-bold h-fit hover:bg-opacity-90 flex items-center gap-1 shadow-md">
                    <CheckCircle size={16} /> Verifikasi
                  </button>
                </div>
              </motion.div>
            ))}
            {users.recipients.filter(u => u.status === "pending").length === 0 && (
              <EmptyState icon={<CheckCircle size={32} />} title="Bersih" description="Tidak ada penerima pending yang butuh verifikasi." />
            )}
          </div>

          {/* CLAIMS VERIFICATION */}
          <div className="flex flex-col gap-4">
            <h2 className="text-lg font-bold flex items-center gap-2"><FileCheck size={20} /> Persetujuan Klaim Donasi</h2>
            {claims.filter(c => c.status === "pending").map((c, i) => (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.05 }} key={c.id} className="bg-white p-4 rounded-xl border shadow-sm hover:shadow-md transition-shadow">
                <div className="flex justify-between">
                  <h3 className="font-bold text-[#1565C0] flex items-center gap-1"><Package size={16} /> Klaim Donasi #{c.donation_id}</h3>
                  <span className="text-xs bg-gray-100 px-2 py-1 rounded font-mono font-bold">Rank #{c.topsis_rank_at_claim}</span>
                </div>
                <p className="text-sm my-2">Lembaga: <b>{c.institution_name}</b></p>
                <div className="flex gap-2 mt-3">
                  <button onClick={() => handleApproveClaim(c.id)} className="bg-[#1565C0] text-white px-4 py-2 rounded-lg text-sm font-bold flex-1 hover:bg-opacity-90 shadow-md">Setujui Klaim</button>
                </div>
              </motion.div>
            ))}
            {claims.filter(c => c.status === "pending").length === 0 && (
              <EmptyState icon={<Package size={32} />} title="Tidak ada antrian" description="Tidak ada klaim donasi pending yang perlu persetujuan." />
            )}
          </div>
        </div>

        {/* Search */}
        <div className="mb-6">
          <input
            type="text"
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Cari user berdasarkan nama atau email..."
            className="w-full max-w-md border border-gray-200 rounded-xl px-4 py-3 bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent outline-none transition-all"
          />
        </div>

        {/* DONOR & RECIPIENT LISTS */}
        <div className="grid md:grid-cols-2 gap-6 pb-12">
          <div className="bg-white rounded-2xl shadow-sm border p-6">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><Building2 size={20} /> Daftar Pendonasi</h2>
            {users.donors.length === 0 ? (
              <EmptyState icon={<Users size={32} />} title="Kosong" description="Belum ada pendonasi terdaftar." />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b text-left text-gray-500">
                      <th className="pb-2 font-semibold">Nama</th>
                      <th className="pb-2 font-semibold">Tipe</th>
                      <th className="pb-2 font-semibold">Total Donasi</th>
                      <th className="pb-2 font-semibold">Status</th>
                      <th className="pb-2 font-semibold"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.donors
                      .filter(d => !search || d.business_name?.toLowerCase().includes(search.toLowerCase()) || d.name?.toLowerCase().includes(search.toLowerCase()) || d.email?.toLowerCase().includes(search.toLowerCase()))
                      .map(d => (
                        <tr key={d.id} className="border-b border-gray-50 hover:bg-gray-50/50 transition-colors">
                          <td className="py-3">
                            <div className="font-medium">{d.business_name || d.name}</div>
                            <div className="text-xs text-gray-400 flex items-center gap-1 mt-0.5"><Mail size={12} />{d.email}</div>
                          </td>
                          <td className="py-3 capitalize text-gray-600">{d.business_type || "-"}</td>
                          <td className="py-3 font-bold">{d.total_donations || 0}</td>
                          <td className="py-3">
                            <span className={`text-xs font-bold px-2 py-1 rounded-full ${d.status === "verified" ? "bg-green-100 text-green-700" : "bg-yellow-100 text-yellow-700"}`}>
                              {d.status === "verified" ? "Terverifikasi" : "Pending"}
                            </span>
                          </td>
                          <td className="py-3">
                            <button
                              onClick={() => setDeleteTarget({ id: d.id, name: d.business_name || d.name })}
                              className="text-red-400 hover:text-red-600 transition-colors"
                              title="Hapus user"
                            >
                              <Trash2 size={16} />
                            </button>
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          <div className="bg-white rounded-2xl shadow-sm border p-6">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><Users size={20} /> Daftar Penerima</h2>
            {users.recipients.length === 0 ? (
              <EmptyState icon={<Users size={32} />} title="Kosong" description="Belum ada penerima terdaftar." />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b text-left text-gray-500">
                      <th className="pb-2 font-semibold">Nama</th>
                      <th className="pb-2 font-semibold">Tipe</th>
                      <th className="pb-2 font-semibold">Urgensi</th>
                      <th className="pb-2 font-semibold">Darurat</th>
                      <th className="pb-2 font-semibold">Status</th>
                      <th className="pb-2 font-semibold"></th>
                    </tr>
                  </thead>
                  <tbody>
                    {users.recipients
                      .filter(r => !search || r.institution_name?.toLowerCase().includes(search.toLowerCase()) || r.name?.toLowerCase().includes(search.toLowerCase()) || r.email?.toLowerCase().includes(search.toLowerCase()))
                      .map(r => (
                        <tr key={r.id} className={`border-b border-gray-50 hover:bg-gray-50/50 transition-colors ${r.emergency === "active" ? 'bg-red-50' : r.emergency === "pending" ? 'bg-yellow-50' : ''}`}>
                          <td className="py-3">
                            <div className="font-medium">{r.institution_name || r.name}</div>
                            <div className="text-xs text-gray-400 flex items-center gap-1 mt-0.5"><Mail size={12} />{r.email}</div>
                          </td>
                          <td className="py-3 capitalize text-gray-600">{r.institution_type?.replace(/_/g, " ") || "-"}</td>
                          <td className="py-3">
                            <span className={`font-bold ${(r.urgency_score || 0) >= 4 ? "text-red-600" : (r.urgency_score || 0) >= 3 ? "text-yellow-600" : "text-gray-600"}`}>
                              {r.urgency_score || "-"}/5
                            </span>
                          </td>
                          <td className="py-3">
                            <button onClick={() => handleEmergencyToggle(r.id)} className={`text-xs font-bold px-3 py-1.5 rounded-lg transition-all ${r.emergency === "active" ? 'bg-[#E53935] text-white hover:bg-red-700' : r.emergency === "pending" ? 'bg-[#F9A825] text-white hover:bg-yellow-600' : 'bg-gray-100 text-gray-500 hover:bg-gray-200'}`}>
                              {r.emergency === "active" ? "Aktif 🚨" : r.emergency === "pending" ? "Pending ⏳" : "Nonaktif"}
                            </button>
                          </td>
                          <td className="py-3">
                            <span className={`text-xs font-bold px-2 py-1 rounded-full ${r.status === "verified" ? "bg-green-100 text-green-700" : "bg-yellow-100 text-yellow-700"}`}>
                              {r.status === "verified" ? "Terverifikasi" : "Pending"}
                            </span>
                          </td>
                          <td className="py-3">
                            <button
                              onClick={() => setDeleteTarget({ id: r.id, name: r.institution_name || r.name })}
                              className="text-red-400 hover:text-red-600 transition-colors"
                              title="Hapus user"
                            >
                              <Trash2 size={16} />
                            </button>
                          </td>
                        </tr>
                      ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Confirm Delete Dialog */}
      <ConfirmDialog
        open={!!deleteTarget}
        title="Hapus User"
        message={`Yakin ingin menghapus "${deleteTarget?.name}"? Data terkait (donasi, klaim) juga akan dihapus.`}
        confirmLabel="Ya, Hapus"
        variant="danger"
        onConfirm={handleDeleteUser}
        onCancel={() => setDeleteTarget(null)}
      />

      {showProfile && (
        <ProfileModal
          user={currentUser}
          profile={profile}
          onClose={() => setShowProfile(false)}
          onUpdate={() => refresh()}
        />
      )}
    </motion.div>
  );
}

