import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import { validateEmail, validatePassword, getErrorClass, getErrorText } from "../lib/validation";
import { LoadingSpinner } from "../components/LoadingSpinner";
import { Eye, EyeOff } from "lucide-react";
import toast from "react-hot-toast";
import { motion } from "motion/react";
import authHero from "../assets/images/auth_hero_1781550749621.webp";

export function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<{ email?: string; password?: string }>({});
  const { login } = useAuth();
  const nav = useNavigate();

  const validate = () => {
    const emailErr = validateEmail(email);
    const passErr = validatePassword(password);
    setErrors({
      email: emailErr.valid ? undefined : emailErr.message,
      password: passErr.valid ? undefined : passErr.message,
    });
    return emailErr.valid && passErr.valid;
  };

  const handleLogin = async (e: any) => {
    e.preventDefault();
    if (!validate()) return;
    setLoading(true);
    try {
      const res = await login(email, password);
      toast.success("Berhasil masuk!");
      if (res.user.role === "admin") nav("/admin");
      else if (res.user.role === "donor") nav("/donor");
      else nav("/recipient");
    } catch (err: any) {
      toast.error(err.message || "Gagal masuk.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F7F4EE] flex text-[#2C2C2C]">
      <div className="hidden lg:block lg:w-1/2 relative">
        <img src={authHero} alt="Heart-warming volunteer" className="absolute inset-0 w-full h-full object-cover" crossOrigin="anonymous" referrerPolicy="no-referrer" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#2D7A4F]/80 to-transparent flex flex-col justify-end p-12 text-white">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
            <h1 className="text-4xl font-bold mb-4">NutriShare</h1>
            <p className="text-lg opacity-90 max-w-md">Menghubungkan surplus pangan dengan mereka yang paling membutuhkan melalui teknologi cerdas dan kepedulian bersama.</p>
          </motion.div>
        </div>
      </div>
      <div className="w-full lg:w-1/2 flex items-center justify-center p-6">
        <motion.div
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          className="bg-white p-8 sm:p-10 rounded-3xl shadow-sm border border-gray-100 max-w-md w-full"
        >
          <h2 className="text-3xl font-bold mb-2">Selamat Datang</h2>
          <p className="text-gray-500 mb-8">Masuk ke akun NutriShare Anda untuk melanjutkan kebaikan hari ini.</p>
          <form onSubmit={handleLogin} className="flex flex-col gap-5">
            <div>
              <label htmlFor="login-email" className="text-sm font-medium mb-1.5 block text-gray-700">Email</label>
              <input
                id="login-email"
                type="email"
                value={email}
                onChange={e => { setEmail(e.target.value); if (errors.email) setErrors(p => ({ ...p, email: undefined })); }}
                onBlur={() => { const r = validateEmail(email); setErrors(p => ({ ...p, email: r.valid ? undefined : r.message })); }}
                className={`w-full border rounded-xl px-4 py-3 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none ${getErrorClass(errors.email)}`}
                required
              />
              {getErrorText(errors.email)}
            </div>
            <div>
              <label htmlFor="login-password" className="text-sm font-medium mb-1.5 block text-gray-700">Password</label>
              <div className="relative">
                <input
                  id="login-password"
                  type={showPassword ? "text" : "password"}
                  value={password}
                  onChange={e => { setPassword(e.target.value); if (errors.password) setErrors(p => ({ ...p, password: undefined })); }}
                  onBlur={() => { const r = validatePassword(password); setErrors(p => ({ ...p, password: r.valid ? undefined : r.message })); }}
                  className={`w-full border rounded-xl px-4 py-3 pr-12 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#52C77F] focus:border-transparent transition-all outline-none ${getErrorClass(errors.password)}`}
                  required
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                >
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>
              {getErrorText(errors.password)}
            </div>
            <button
              disabled={loading}
              type="submit"
              className="w-full bg-[#2D7A4F] text-white py-3.5 rounded-xl font-bold mt-2 hover:bg-opacity-90 transform hover:-translate-y-0.5 transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:transform-none flex items-center justify-center gap-2"
            >
              {loading ? <><LoadingSpinner size={18} /> Memproses...</> : "Masuk ke Sistem"}
            </button>
          </form>
          <div className="mt-8 text-center border-t border-gray-100 pt-6">
            <span className="text-gray-500">Belum punya akun? </span>
            <Link to="/register/donor" className="text-[#2D7A4F] font-bold hover:underline">Daftar di sini.</Link>
          </div>
        </motion.div>
      </div>
    </div>
  );
}

