      { key: "address", fn: () => validateRequired(form.address, "Alamat") },
      { key: "resident_count", fn: () => validateNumber(form.resident_count, "Jumlah Penghuni") },
    ];
    const newErrors: FieldErrors = {};
    let valid = true;
    fields.forEach(f => {
      const r = f.fn();
      if (!r.valid) { newErrors[f.key] = r.message; valid = false; }
    });
    setErrors(newErrors);
    return valid;
  };

  const handleRegister = async (e: any) => {
    e.preventDefault();
    if (!validateAll()) return;
    setLoading(true);
    try {
      await api.fetchJSON("/api/auth/register/recipient", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form)
      });
      toast.success("Pendaftaran berhasil, tunggu verifikasi oleh admin (penilaian urgensi).");
      nav("/login");
    } catch (err: any) {
      toast.error(err.message || "Gagal mendaftar");
    } finally {
      setLoading(false);
    }
  };

  const update = (field: string, value: string) => {
    setForm(f => ({ ...f, [field]: value }));
    if (errors[field]) setErrors(p => ({ ...p, [field]: undefined }));
  };

  return (
    <div className="min-h-screen bg-[#F7F4EE] flex flex-row-reverse text-[#2C2C2C]">
      <div className="hidden lg:block lg:w-5/12 relative">
        <img src={recipientImg} alt="Children in community center" className="absolute inset-0 w-full h-full object-cover" crossOrigin="anonymous" referrerPolicy="no-referrer" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#1565C0]/90 to-transparent flex flex-col justify-end p-12 text-white">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }}>
            <h1 className="text-3xl font-bold mb-3">Menerima dengan Terhormat</h1>
            <p className="opacity-90 leading-relaxed">Daulat pangan untuk semua. Daftarkan lembaga Anda agar kami dapat menghubungkan donasi gizi yang tepat ke tempat yang tepat.</p>
          </motion.div>
        </div>
      </div>
      <div className="w-full lg:w-7/12 flex flex-col justify-center p-6 sm:p-12 overflow-y-auto max-h-screen">
        <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="max-w-xl w-full mx-auto">
          <div className="mb-8">
            <h2 className="text-3xl font-bold mb-2">Daftar Penerima Bantuan</h2>
            <p className="text-gray-500">Panti Asuhan, Rumah Singgah, atau Entitas Sosial.</p>
          </div>
          <form onSubmit={handleRegister} className="flex flex-col gap-5 text-sm">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div>
                <label htmlFor="recip-institution-name" className="block text-gray-700 font-medium mb-1">Nama Lembaga</label>
                <input id="recip-institution-name" placeholder="Nama Lembaga" value={form.institution_name}
                  onChange={e => update("institution_name", e.target.value)}
                  onBlur={() => validateField("institution_name", form.institution_name)}
                  className={`w-full border border-gray-200 p-3.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#1565C0] focus:border-transparent transition-all outline-none ${getErrorClass(errors.institution_name)}`} required />
                {getErrorText(errors.institution_name)}
              </div>
              <div>
                <label htmlFor="recip-institution-type" className="block text-gray-700 font-medium mb-1">Tipe Lembaga</label>
                <select id="recip-institution-type" value={form.institution_type} onChange={e => update("institution_type", e.target.value)}
                  className="w-full border border-gray-200 p-3.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#1565C0] focus:border-transparent transition-all outline-none">
                  <option value="panti_asuhan">Panti Asuhan</option>
                  <option value="rumah_singgah">Rumah Singgah</option>
                  <option value="lembaga_sosial">Lembaga Sosial Lain</option>
                </select>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <div>
                <label htmlFor="recip-email" className="block text-gray-700 font-medium mb-1">Email login</label>
