                  onChange={e => update("email", e.target.value)}
                  onBlur={() => validateField("email", form.email)}
                  className={`w-full border border-gray-200 p-3.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#1565C0] focus:border-transparent transition-all outline-none ${getErrorClass(errors.email)}`} required />
                {getErrorText(errors.email)}
              </div>
              <div>
                <label htmlFor="recip-password" className="block text-gray-700 font-medium mb-1">Password</label>
                <div className="relative">
                  <input id="recip-password" placeholder="Min. 6 karakter" type={showPassword ? "text" : "password"} value={form.password}
                    onChange={e => update("password", e.target.value)}
                    onBlur={() => validateField("password", form.password)}
                    className={`w-full border border-gray-200 p-3.5 rounded-xl pr-12 bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#1565C0] focus:border-transparent transition-all outline-none ${getErrorClass(errors.password)}`} required />
                  <button type="button" onClick={() => setShowPassword(!showPassword)}
