              </div>
              <div>
                <label htmlFor="recip-vitaminc" className="block text-gray-700 font-medium mb-1">Kebutuhan Vitamin C Harian (mg)</label>
                <input id="recip-vitaminc" placeholder="Estimasi(mg)" type="number" value={form.daily_vitamin_c_need}
                  onChange={e => update("daily_vitamin_c_need", e.target.value)}
