              </div>
            </div>

            <div>
              <label htmlFor="recip-address" className="block text-gray-700 font-medium mb-1">Alamat Lengkap</label>
              <textarea id="recip-address" placeholder="Alamat" value={form.address}
                onChange={e => update("address", e.target.value)}
                onBlur={() => validateField("address", form.address)}
                className={`w-full border border-gray-200 p-3.5 rounded-xl bg-gray-50 focus:bg-white focus:ring-2 focus:ring-[#1565C0] focus:border-transparent transition-all outline-none ${getErrorClass(errors.address)}`} rows={2} required />
              {getErrorText(errors.address)}
            </div>

            <div className="bg-gray-50 flex-col flex border border-gray-200 p-5 rounded-2xl relative z-0 mt-2">
              <h3 className="font-bold mb-2 flex items-center gap-2 text-sm"><MapPin size={16} className="text-[#1565C0]" /> Pilih Lokasi Lembaga di Peta</h3>
              <p className="text-xs text-gray-500 mb-4">Klik atau geser pin merah untuk menandai lokasi agar driver mudah menemukan Anda.</p>
              <div className="h-[250px] w-full rounded-xl overflow-hidden shadow-inner border border-gray-200 relative z-0">
                <LocationPicker
                  lat={parseFloat(form.latitude)}
                  lng={parseFloat(form.longitude)}
                  onChange={(lat: number, lng: number) => setForm({ ...form, latitude: lat.toString(), longitude: lng.toString() })}
                />
              </div>
            </div>

            <button disabled={loading} type="submit"
              className="w-full bg-[#1565C0] text-white py-4 rounded-xl font-bold mt-4 hover:bg-opacity-90 transform hover:-translate-y-0.5 transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:transform-none text-base flex items-center justify-center gap-2">
              {loading ? <><LoadingSpinner size={18} /> Memproses...</> : "Kirim Pendaftaran"}
            </button>
          </form>
          <div className="mt-8 text-center border-t border-gray-100 pt-6">
            <span className="text-gray-500">Sudah punya akun? </span>
            <Link to="/login" className="text-[#1565C0] font-bold hover:underline">Masuk di sini.</Link>
          </div>
        </motion.div>
      </div>
    </div>
  );
}

