function Countdown({ validUntil }: { validUntil: string }) {
  const [timeLeft, setTimeLeft] = useState("");

  useEffect(() => {
    const timer = setInterval(() => {
      const diff = new Date(validUntil).getTime() - new Date().getTime();
      if (diff <= 0) { setTimeLeft("Kadaluarsa"); clearInterval(timer); }
      else {
        const h = Math.floor(diff / (1000 * 60 * 60));
        const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
        const s = Math.floor((diff % (1000 * 60)) / 1000);
        setTimeLeft(`${h}j ${m}m ${s}d`);
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [validUntil]);

  return (
    <span className={`font-mono text-sm font-bold ${timeLeft === "Kadaluarsa" ? "text-[#E53935]" : "text-gray-600"}`}>
      {timeLeft === "Kadaluarsa" ? "⏰ Kadaluarsa" : `⏱ ${timeLeft}`}
    </span>
  );
}

function NotificationPanel({ notifications, onMarkRead, onClose }: {
  notifications: Notification[];
  onMarkRead: (id: number) => void;
  onClose: () => void;
}) {
  const unread = notifications.filter(n => !n.is_read);

  return (
    <motion.div
      initial={{ opacity: 0, y: -10, scale: 0.95 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: -10, scale: 0.95 }}
      transition={{ duration: 0.15 }}
      className="absolute right-0 mt-3 w-80 bg-white shadow-xl rounded-2xl overflow-hidden z-50 border border-gray-100"
    >
      <div className="p-4 border-b bg-gradient-to-r from-[#F7F4EE] to-white">
        <div className="flex items-center justify-between">
          <h3 className="font-bold text-sm">Notifikasi</h3>
          {unread.length > 0 && (
            <span className="bg-[#E53935] text-white text-[10px] px-2 py-0.5 rounded-full font-bold">
              {unread.length} baru
            </span>
          )}
        </div>
      </div>
      <div className="max-h-72 overflow-y-auto" onClick={onClose}>
        {notifications.length === 0 && (
          <div className="p-8 text-center">
            <Bell size={32} className="mx-auto text-gray-300 mb-2" />
            <p className="text-sm text-gray-500">Belum ada notifikasi.</p>
          </div>
        )}
        {notifications.map((n, i) => (
          <motion.div
            key={n.id}
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: i * 0.03 }}
            onClick={() => onMarkRead(n.id)}
            className={`p-4 border-b text-sm cursor-pointer transition-all ${
              !n.is_read
                ? "bg-blue-50/50 hover:bg-blue-100/50 border-l-2 border-l-[#1565C0]"
                : "hover:bg-gray-50 border-l-2 border-l-transparent"
            }`}
          >
            <p className="font-bold text-gray-800">{n.title}</p>
            <p className="text-gray-600 mt-0.5">{n.message}</p>
            <p className="text-[10px] text-gray-400 mt-1.5">
              {formatDistanceToNow(new Date(n.created_at), { addSuffix: true, locale: idLocale })}
            </p>
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
}

function CollapsibleSection({ title, icon, badge, children, defaultOpen = true }: {
  title: string; icon: React.ReactNode; badge?: React.ReactNode; children: React.ReactNode; defaultOpen?: boolean;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <motion.div layout className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
      <button onClick={() => setOpen(!open)} className="w-full flex items-center justify-between p-5 hover:bg-gray-50/50 transition-colors">
        <div className="flex items-center gap-3">
          <span className="text-[#2D7A4F]">{icon}</span>
          <span className="font-bold text-gray-800">{title}</span>
          {badge}
        </div>
        <motion.div animate={{ rotate: open ? 180 : 0 }} transition={{ duration: 0.2 }}>
          <ChevronDown size={20} className="text-gray-400" />
        </motion.div>
      </button>
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2 }}
            className="overflow-hidden"
          >
            <div className="px-5 pb-5">{children}</div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

