                  className={`bg-white p-5 rounded-2xl shadow-sm ${d.my_claim_status === 'pending' ? 'ring-2 ring-yellow-400' : 'border border-gray-100'} flex flex-col gap-3 relative overflow-hidden card-hover`}
                >
                  {d.rank === 1 && !d.my_claim_status && (
                    <div className="absolute top-0 right-0 bg-gradient-to-l from-[#E53935] to-[#E53935]/80 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl shadow-sm">PRIORITAS</div>
                  )}
                  {d.my_claim_status === "pending" && (
                    <div className="absolute top-0 right-0 bg-gradient-to-l from-yellow-500 to-yellow-500/80 text-white text-[10px] font-bold px-3 py-1 rounded-bl-xl shadow-sm">MENUNGGU ADMIN</div>
                  )}
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1 min-w-0">
                      <h3 className="font-bold text-lg leading-tight">{d.food_name}</h3>
                      <p className="text-sm text-gray-500 mt-1 flex items-center gap-2 flex-wrap">
                        <span className="font-medium text-gray-700">{d.donor_name}</span>
                        <span className="text-gray-300">•</span>
                        <span className="flex items-center gap-1"><Package size={14} /> {d.portion_count} porsi</span>
                      </p>
                    </div>
                    <div className="text-right shrink-0">
                      <div className={`text-sm font-bold ${d.rank === 1 ? 'text-[#E53935]' : 'text-gray-500'}`}>Rank #{d.rank}</div>
                      <Countdown validUntil={d.valid_until} />
                    </div>
                  </div>
                  <div className="bg-gray-50 p-3 rounded-xl">
                    <div className="flex justify-between text-xs text-gray-600 mb-2">
                      <span>Protein: {d.protein_per_portion}g/porsi</span>
                      <span>Kalori: {d.calorie_per_portion}/porsi</span>
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-[10px] text-gray-400">% Pemenuhan Protein/Porsi</span>
                      <span className="text-xs font-bold text-[#2D7A4F]">{Math.min((d.protein_per_portion / (profile.daily_protein_need || 1)) * 100, 100).toFixed(0)}%</span>
                    </div>
                    <div className="w-full bg-gray-200 rounded-full h-1.5 mt-1 overflow-hidden">
                      <motion.div initial={{ width: 0 }} animate={{ width: `${Math.min((d.protein_per_portion / (profile.daily_protein_need || 1)) * 100, 100)}%` }} transition={{ duration: 1, delay: i * 0.1 }}
                        className="bg-[#2D7A4F] h-1.5 rounded-full"
                      />
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => loadTopsis(d.id)} className="flex-1 border border-gray-200 text-sm font-bold py-2.5 rounded-xl hover:bg-gray-50 transition-all flex items-center justify-center gap-1.5">
                      <BarChart3 size={16} /> Analisis TOPSIS
                    </button>
                    {d.my_claim_status === "pending" ? (
                      <div className="flex-1 bg-yellow-50 text-yellow-800 text-sm font-bold py-2.5 rounded-xl text-center border border-yellow-200">
                        Menunggu Admin
                      </div>
                    ) : (
                      <button onClick={() => handleClaim(d.id)}
                        disabled={d.rank !== 1}
                        className={`flex-1 text-white text-sm font-bold py-2.5 rounded-xl transition-all ${
                          d.rank === 1
                            ? 'bg-[#2D7A4F] hover:bg-opacity-90 shadow-md hover:shadow-lg active:scale-[0.98]'
                            : 'bg-gray-300 cursor-not-allowed'
                        }`}
                      >
                        {d.rank === 1 ? "Klaim Donasi" : "Rank #1 untuk klaim"}
                      </button>
                    )}
                  </div>
                </motion.div>
              ))}
            </div>

            {/* TOPSIS Panel */}
            <div className="bg-white p-5 rounded-2xl border border-gray-100 shadow-sm h-fit sticky top-24">
              {selectedDonation ? (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                  <h3 className="font-bold text-[#1565C0] mb-1">Analisis TOPSIS</h3>
                  <p className="text-xs text-gray-500 mb-4">Donasi #{selectedDonation}</p>
                  <div className="overflow-x-auto">
                    <table className="w-full text-xs">
                      <thead className="bg-[#F7F4EE] text-gray-600">
                        <tr>
                          <th className="p-2 border-b text-center">#</th>
                          <th className="p-2 border-b">Lembaga</th>
                          <th className="p-2 border-b">Ci</th>
                        </tr>
                      </thead>
                      <tbody>
                        {topsisData.map(t => (
                          <tr key={t.id} className={t.recipient_id === user.id ? "bg-[#E8F5E9] font-bold" : "hover:bg-gray-50"}>
                            <td className="p-2 border-b text-center">#{t.rank_position}</td>
                            <td className="p-2 border-b truncate max-w-[100px]">{t.institution_name}</td>
                            <td className="p-2 border-b text-[#2D7A4F]">{t.ci_score.toFixed(4)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </motion.div>
              ) : (
                <div className="flex flex-col items-center justify-center text-center text-gray-400 py-8">
                  <BarChart3 size={40} className="mb-3 opacity-50" />
                  <p className="text-sm">Pilih "Analisis TOPSIS" pada donasi untuk melihat detail peringkat.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* History Tab */}
        {activeTab === "history" && (
          <div>
            {completedHistory.length === 0 ? (
              <EmptyState icon={<FileText size={40} />} title="Belum Ada Riwayat"
                description="Donasi yang sudah selesai akan muncul di sini beserta tombol untuk memberikan ulasan."
              />
            ) : (
              <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
                {completedHistory.map((d, i) => (
                  <motion.div key={d.id} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.03 }}
                    className="bg-white rounded-2xl p-5 border border-gray-100 shadow-sm card-hover"
                  >
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <h3 className="font-bold text-lg">{d.food_name}</h3>
                        <p className="text-sm text-gray-500">Dari: {d.donor_name}</p>
                      </div>
                      {d.has_reviewed ? (
                        <span className="bg-green-100 text-green-700 text-xs font-bold px-3 py-1 rounded-full flex items-center gap-1">
                          <Star size={12} fill="currentColor" /> Dinilai
                        </span>
                      ) : (
                        <button onClick={() => setSelectedReviewDonation(d)}
                          className="bg-white border-2 border-[#1565C0] text-[#1565C0] px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-[#E3F2FD] transition-all shrink-0"
                        >
                          Beri Nilai
                        </button>
                      )}
                    </div>
                    {d.completed_at && (
                      <p className="text-[10px] text-gray-400">
                        Selesai: {new Date(d.completed_at).toLocaleDateString("id-ID", { day: "numeric", month: "short", year: "numeric" })}
                      </p>
                    )}
                  </motion.div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* Map Tab */}
        {activeTab === "map" && (
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><MapPin size={20} className="text-[#2D7A4F]" /> Peta Target Distribusi</h2>
            <div className="h-[400px] w-full rounded-xl overflow-hidden border">
              {profile.latitude && (
                <MapContainer center={[profile.latitude, profile.longitude]} zoom={13} style={{ height: "100%", width: "100%" }}>
                  <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" referrerPolicy="origin" />
                  <Marker position={[profile.latitude, profile.longitude]} icon={recipientIcon}>
                    <Popup><b>{profile.institution_name}</b><br />Lembaga Anda</Popup>
                  </Marker>
                  {mapData.donors.map(donor => (
                    <Marker key={donor.id} position={[donor.latitude, donor.longitude]} icon={donorIcon}>
                      <Popup><b>{donor.business_name}</b><br />{donor.address}</Popup>
                    </Marker>
                  ))}
                  {activeDonations.filter(d => d.rank === 1).map(d => {
                    const donorInfo = mapData.donors.find(p => p.user_id === d.donor_id);
                    return donorInfo ? (
                      <Polyline key={`line-${d.id}`} positions={[[profile.latitude, profile.longitude], [donorInfo.latitude, donorInfo.longitude]]} color="#E53935" weight={3} dashArray="5, 10" />
                    ) : null;
                  })}
                </MapContainer>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Modals */}
      <AnimatePresence>
        {selectedReviewDonation && (
          <ReviewModal donation={selectedReviewDonation} onClose={() => setSelectedReviewDonation(null)} onReviewed={loadData} />
        )}
        {trackingData && (
          <LiveTrackingModal donation={trackingData} user={user} onClose={() => setTrackingData(null)} onComplete={loadData} />
        )}
        {showProfile && (
          <ProfileModal user={user} profile={profile} onClose={() => setShowProfile(false)} onUpdate={() => refresh()} />
        )}
      </AnimatePresence>
    </motion.div>
  );
}

