283	                      <th className="pb-2 font-semibold">Tipe</th>
284	                      <th className="pb-2 font-semibold">Total Donasi</th>
285	                      <th className="pb-2 font-semibold">Status</th>
286	                      <th className="pb-2 font-semibold"></th>
287	                    </tr>
288	                  </thead>
289	                  <tbody>
290	                    {users.donors
291	                      .filter(d => !search || d.business_name?.toLowerCase().includes(search.toLowerCase()) || d.name?.toLowerCase().includes(search.toLowerCase()) || d.email?.toLowerCase().includes(search.toLowerCase()))
292	                      .map(d => (
293	                        <tr key={d.id} className="border-b border-gray-50 hover:bg-gray-50/50 transition-colors">
294	                          <td className="py-3">
295	                            <div className="font-medium">{d.business_name || d.name}</div>
296	                            <div className="text-xs text-gray-400 flex items-center gap-1 mt-0.5"><Mail size={12} />{d.email}</div>
297	                          </td>
298	                          <td className="py-3 capitalize text-gray-600">{d.business_type || "-"}</td>
