308	                              className="text-red-400 hover:text-red-600 transition-colors"
309	                              title="Hapus user"
310	                            >
311	                              <Trash2 size={16} />
312	                            </button>
313	                          </td>
314	                        </tr>
315	                      ))}
316	                  </tbody>
317	                </table>
318	              </div>
319	            )}
320	          </div>
321	
322	          <div className="bg-white rounded-2xl shadow-sm border p-6">
323	            <h2 className="text-lg font-bold mb-4 flex items-center gap-2"><Users size={20} /> Daftar Penerima</h2>
324	            {users.recipients.length === 0 ? (
325	              <EmptyState icon={<Users size={32} />} title="Kosong" description="Belum ada penerima terdaftar." />
326	            ) : (
327	              <div className="overflow-x-auto">
328	                <table className="w-full text-sm">
329	                  <thead>
330	                    <tr className="border-b text-left text-gray-500">
331	                      <th className="pb-2 font-semibold">Nama</th>
332	                      <th className="pb-2 font-semibold">Tipe</th>
333	                      <th className="pb-2 font-semibold">Urgensi</th>
334	                      <th className="pb-2 font-semibold">Darurat</th>
335	                      <th className="pb-2 font-semibold">Status</th>
336	                      <th className="pb-2 font-semibold"></th>
337	                    </tr>
338	                  </thead>
339	                  <tbody>
