import { useState, useEffect, useRef } from "react";
import { Link } from "react-router-dom";
import { Heart, Search, Shield, ArrowRight, Award, Star, Menu, X, Upload, Cloud, Truck, BarChart3 } from "lucide-react";
import { api } from "../lib/api";
import { motion, AnimatePresence } from "motion/react";

import heroImg from "../assets/images/hero_food_donation_1781547580796.webp";
import hotelLogo from "../assets/images/hotel_logo_1781548674916.webp";
import restaurantLogo from "../assets/images/restaurant_logo_1781548689113.webp";
import cafeLogo from "../assets/images/cafe_logo_1781548701950.webp";
import impactImg from "../assets/images/impact_image_1781550893332.webp";

function useScrollPosition() {
  const [scrollY, setScrollY] = useState(0);
  useEffect(() => {
    const handle = () => setScrollY(window.scrollY);
    window.addEventListener("scroll", handle, { passive: true });
    return () => window.removeEventListener("scroll", handle);
  }, []);
  return scrollY;
}

function AnimatedCounter({ target, suffix = "" }: { target: number; suffix?: string }) {
  const [count, setCount] = useState(0);
  const ref = useRef<HTMLDivElement>(null);
  const done = useRef(false);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !done.current) {
          done.current = true;
          const duration = 1500;
          const steps = 60;
          const increment = target / steps;
          let current = 0;
          const timer = setInterval(() => {
            current += increment;
            if (current >= target) {
              setCount(target);
              clearInterval(timer);
            } else {
              setCount(Math.floor(current));
            }
          }, duration / steps);
        }
      },
      { threshold: 0.3 }
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [target]);

  return (
    <div ref={ref} className="text-5xl font-bold mb-2 font-mono drop-shadow-md">
      {count}{suffix}
    </div>
  );
}

export default function Home() {
  const [topDonors, setTopDonors] = useState<any[]>([]);
  const [mobileOpen, setMobileOpen] = useState(false);
  const scrollY = useScrollPosition();
  const isScrolled = scrollY > 20;

  useEffect(() => {
    api.fetchJSON("/api/public/top-donors").then(setTopDonors).catch(console.error);
  }, []);

  return (
    <div className="min-h-screen bg-[#F7F4EE] text-[#2C2C2C] font-sans">
      {/* Sticky Nav */}
      <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled ? "bg-white/90 backdrop-blur-lg shadow-sm" : "bg-transparent"
      }`}>
        <div className="max-w-7xl mx-auto flex items-center justify-between px-6 py-4">
          <Link to="/" className="text-2xl font-bold tracking-tight text-[#2D7A4F] flex items-center gap-2">
            <Heart className="fill-current text-[#52C77F]" />
            NUTRI-SHARE
          </Link>

          {/* Desktop nav */}
          <div className="hidden md:flex items-center gap-6">
            <Link to="/tentang" className="text-sm font-medium text-gray-600 hover:text-[#2D7A4F] transition-colors">Tentang</Link>
            <a href="#cara-kerja" className="text-sm font-medium text-gray-600 hover:text-[#2D7A4F] transition-colors">Cara Kerja</a>
            <a href="#dampak" className="text-sm font-medium text-gray-600 hover:text-[#2D7A4F] transition-colors">Dampak</a>
            {topDonors.length > 0 && (
              <a href="#pahlawan" className="text-sm font-medium text-gray-600 hover:text-[#2D7A4F] transition-colors">Pahlawan</a>
            )}
            <div className="flex gap-3 ml-4">
              <Link to="/login" className="px-4 py-2 text-sm font-medium text-gray-700 border border-gray-300 rounded-full hover:border-[#2D7A4F] hover:text-[#2D7A4F] transition-all">
                Masuk
              </Link>
