import { Link } from "react-router-dom";
import { motion } from "motion/react";
import { Heart, ArrowRight, Menu, X, TrendingUp, Users, Leaf, Award, Globe, BarChart3, Target, CheckCircle } from "lucide-react";
import { useState, useEffect, useRef } from "react";

function useScrollPosition() {
  const [scrollY, setScrollY] = useState(0);
  useEffect(() => { const h = () => setScrollY(window.scrollY); window.addEventListener("scroll", h, { passive: true }); return () => window.removeEventListener("scroll", h); }, []);
  return scrollY;
}

function AnimatedCounter({ target, suffix = "" }: { target: number; suffix?: string }) {
  const [count, setCount] = useState(0);
  const ref = useRef<HTMLDivElement>(null);
  const done = useRef(false);
  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting && !done.current) {
        done.current = true;
        const duration = 1500, steps = 60, increment = target / steps;
        let current = 0;
        const timer = setInterval(() => { current += increment; if (current >= target) { setCount(target); clearInterval(timer); } else setCount(Math.floor(current)); }, duration / steps);
      }
    }, { threshold: 0.3 });
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [target]);
  return <div ref={ref} className="text-5xl font-bold mb-2 font-mono drop-shadow-md">{count}{suffix}</div>;
}

export default function Impact() {
  const [mobileOpen, setMobileOpen] = useState(false);
  const scrollY = useScrollPosition();
  const isScrolled = scrollY > 20;
  const NavLink = ({ to, children }: { to: string; children: React.ReactNode }) => (<Link to={to} className="text-sm font-medium text-gray-600 hover:text-[#2D7A4F] transition-colors">{children}</Link>);

  return (
    <div className="min-h-screen bg-[#F7F4EE] text-[#2C2C2C] font-sans">
      <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? "bg-white/90 backdrop-blur-lg shadow-sm" : "bg-transparent"}`}>
        <div className="max-w-7xl mx-auto flex items-center justify-between px-6 py-4">
          <Link to="/" className="text-2xl font-bold tracking-tight text-[#2D7A4F] flex items-center gap-2"><Heart className="fill-current text-[#52C77F]" />NUTRI-SHARE</Link>
          <div className="hidden md:flex items-center gap-6">
            <NavLink to="/">Beranda</NavLink>
            <NavLink to="/tentang">Tentang</NavLink>
            <NavLink to="/cara-kerja">Cara Kerja</NavLink>
            <Link to="/dampak" className="text-sm font-medium text-[#2D7A4F] font-bold border-b-2 border-[#2D7A4F]">Dampak</Link>
            <NavLink to="/pahlawan">Pahlawan</NavLink>
            <div className="flex gap-3 ml-4">
              <Link to="/login" className="px-4 py-2 text-sm font-medium text-gray-700 border border-gray-300 rounded-full hover:border-[#2D7A4F] hover:text-[#2D7A4F] transition-all">Masuk</Link>
              <Link to="/register/donor" className="px-4 py-2 text-sm font-medium bg-[#2D7A4F] text-white rounded-full hover:bg-opacity-90 transition-all shadow-sm">Donasi Pangan</Link>
            </div>
          </div>
          <button onClick={() => setMobileOpen(true)} className="md:hidden p-2 text-gray-600"><Menu size={24} /></button>
        </div>
      </nav>
      {mobileOpen && (
        <div className="fixed inset-0 z-[100] bg-black/40 md:hidden" onClick={() => setMobileOpen(false)}>
          <div className="absolute right-0 top-0 bottom-0 w-72 bg-white shadow-2xl p-6" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-8"><span className="font-bold text-[#2D7A4F] flex items-center gap-2"><Heart className="fill-current text-[#52C77F]" size={20} />NUTRI-SHARE</span><button onClick={() => setMobileOpen(false)} className="p-2 text-gray-500"><X size={24} /></button></div>
            <div className="flex flex-col gap-4">
              {["/", "Beranda", "/tentang", "Tentang", "/cara-kerja", "Cara Kerja", "/dampak", "Dampak", "/pahlawan", "Pahlawan"].map((p, i) => i % 2 === 0 ? null : (
                <Link key={p} to={["/","/tentang","/cara-kerja","/dampak","/pahlawan"][i/2|0]} onClick={() => setMobileOpen(false)} className="py-3 border-b border-gray-100 font-medium">{p}</Link>
              ))}
              <div className="mt-6 flex flex-col gap-3">
                <Link to="/login" onClick={() => setMobileOpen(false)} className="text-center py-3 border border-gray-300 rounded-full font-medium">Masuk</Link>
                <Link to="/register/donor" onClick={() => setMobileOpen(false)} className="text-center py-3 bg-[#2D7A4F] text-white rounded-full font-medium">Donasi Pangan</Link>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Hero */}
      <section className="relative pt-28 pb-16 md:pt-36 md:pb-20 overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-[#2D7A4F]/10 via-transparent to-[#1565C0]/10" />
        <div className="max-w-4xl mx-auto px-6 text-center relative">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
            <h1 className="text-4xl md:text-5xl font-bold mb-6 leading-tight">Dampak <span className="text-[#2D7A4F]">Nyata</span></h1>
            <p className="text-lg text-gray-600 max-w-2xl mx-auto leading-relaxed">Bersama kita mewujudkan perubahan nyata — mengurangi food waste, meningkatkan gizi masyarakat, dan mendukung pencapaian Sustainable Development Goals.</p>
          </motion.div>
        </div>
      </section>

      {/* Impact Numbers */}
      <section className="max-w-5xl mx-auto px-6 py-8">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 text-center">
          {[
            { target: 1200, suffix: "+", label: "Kg Food Waste Terselamatkan", icon: Leaf },
            { target: 850, suffix: "", label: "Anak & Lansia Terbantu", icon: Users },
            { target: 45, suffix: "+", label: "Mitra HoReKa", icon: Award },
          ].map((item, i) => (
            <motion.div key={i} initial={{ opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: i * 0.1 }}
              className="bg-white rounded-2xl p-8 shadow-sm border border-gray-100 card-hover"
            >
              <div className="w-16 h-16 bg-[#E8F5E9] rounded-full flex items-center justify-center mx-auto mb-4">
                <item.icon size={32} className="text-[#2D7A4F]" />
              </div>
              <AnimatedCounter target={item.target} suffix={item.suffix} />
              <div className="text-gray-500 font-medium">{item.label}</div>
            </motion.div>
          ))}
        </div>
      </section>

      {/* Problem vs Solution */}
      <section className="max-w-6xl mx-auto px-6 py-16">
        <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} className="text-center mb-12">
          <h2 className="text-3xl font-bold mb-4">Masalah vs Solusi</h2>
          <p className="text-gray-500 max-w-lg mx-auto">Bagaimana NUTRI-SHARE menjawab tantangan food waste dan malnutrisi.</p>
        </motion.div>
        <div className="grid md:grid-cols-2 gap-8">
          <motion.div initial={{ opacity: 0, x: -20 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true, margin: "-50px" }}
            className="space-y-4"
          >
