  const [topDonors, setTopDonors] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<string>("all");
  const scrollY = useScrollPosition();
  const isScrolled = scrollY > 20;

  useEffect(() => {
    api.fetchJSON("/api/public/top-donors").then(data => { setTopDonors(data); setLoading(false); }).catch(() => setLoading(false));
  }, []);

  const getLogo = (type: string, logoUrl?: string) => {
    if (logoUrl) return logoUrl;
    const logos: Record<string, string> = { hotel: hotelLogo, restoran: restaurantLogo, kafe: cafeLogo };
    return logos[type] || "";
  };

  const filtered = filter === "all" ? topDonors : topDonors.filter(d => d.type === filter);
  const NavLink = ({ to, children }: { to: string; children: React.ReactNode }) => (<Link to={to} className="text-sm font-medium text-gray-600 hover:text-[#2D7A4F] transition-colors">{children}</Link>);

  return (
    <div className="min-h-screen bg-[#F7F4EE] text-[#2C2C2C] font-sans">
      <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${isScrolled ? "bg-white/90 backdrop-blur-lg shadow-sm" : "bg-transparent"}`}>
        <div className="max-w-7xl mx-auto flex items-center justify-between px-6 py-4">
          <Link to="/" className="text-2xl font-bold tracking-tight text-[#2D7A4F] flex items-center gap-2"><Heart className="fill-current text-[#52C77F]" />NUTRI-SHARE</Link>
          <div className="hidden md:flex items-center gap-6">
            <NavLink to="/">Beranda</NavLink>
            <NavLink to="/tentang">Tentang</NavLink>
            <NavLink to="/cara-kerja">Cara Kerja</NavLink>
            <NavLink to="/dampak">Dampak</NavLink>
            <Link to="/pahlawan" className="text-sm font-medium text-[#2D7A4F] font-bold border-b-2 border-[#2D7A4F]">Pahlawan</Link>
            <div className="flex gap-3 ml-4">
              <Link to="/login" className="px-4 py-2 text-sm font-medium text-gray-700 border border-gray-300 rounded-full hover:border-[#2D7A4F] hover:text-[#2D7A4F] transition-all">Masuk</Link>
              <Link to="/register/donor" className="px-4 py-2 text-sm font-medium bg-[#2D7A4F] text-white rounded-full hover:bg-opacity-90 transition-all shadow-sm">Donasi Pangan</Link>
            </div>
          </div>
          <button onClick={() => setMobileOpen(true)} className="md:hidden p-2 text-gray-600"><Menu size={24} /></button>
        </div>
      </nav>
      {mobileOpen && (
        <div className="fixed inset-0 z-[100] bg-black/40 md:hidden" onClick={() => setMobileOpen(false)}>
          <div className="absolute right-0 top-0 bottom-0 w-72 bg-white shadow-2xl p-6" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-8"><span className="font-bold text-[#2D7A4F] flex items-center gap-2"><Heart className="fill-current text-[#52C77F]" size={20} />NUTRI-SHARE</span><button onClick={() => setMobileOpen(false)} className="p-2 text-gray-500"><X size={24} /></button></div>
            <div className="flex flex-col gap-4">
              {[{ p: "/", l: "Beranda" }, { p: "/tentang", l: "Tentang" }, { p: "/cara-kerja", l: "Cara Kerja" }, { p: "/dampak", l: "Dampak" }, { p: "/pahlawan", l: "Pahlawan" }].map(({ p, l }) => (
                <Link key={p} to={p} onClick={() => setMobileOpen(false)} className={`py-3 border-b border-gray-100 font-medium ${p === "/pahlawan" ? "text-[#2D7A4F] font-bold" : ""}`}>{l}</Link>
              ))}
              <div className="mt-6 flex flex-col gap-3">
                <Link to="/login" onClick={() => setMobileOpen(false)} className="text-center py-3 border border-gray-300 rounded-full font-medium">Masuk</Link>
                <Link to="/register/donor" onClick={() => setMobileOpen(false)} className="text-center py-3 bg-[#2D7A4F] text-white rounded-full font-medium">Donasi Pangan</Link>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Hero */}
      <section className="relative pt-28 pb-16 md:pt-36 md:pb-20 overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-br from-yellow-50 via-white to-orange-50" />
        <div className="max-w-4xl mx-auto px-6 text-center relative">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
            <div className="inline-flex items-center gap-2 bg-white/80 backdrop-blur-sm border border-[#F5A623]/20 px-4 py-2 rounded-full text-sm font-bold text-[#F5A623] mb-6 shadow-sm"><Award size={16} /> Setiap Donor Adalah Pahlawan</div>
            <h1 className="text-4xl md:text-5xl font-bold mb-6 leading-tight">Pahlawan <span className="text-[#F5A623]">Pangan</span></h1>
            <p className="text-lg text-gray-600 max-w-2xl mx-auto leading-relaxed">
              Apresiasi untuk para pahlawan pangan — hotel, restoran, dan kafe yang telah berkontribusi aktif mendistribusikan surplus pangan bergizi kepada mereka yang membutuhkan.
            </p>
          </motion.div>
        </div>
      </section>

      {/* Stats bar */}
      {!loading && topDonors.length > 0 && (
        <section className="max-w-5xl mx-auto px-6 -mt-8 mb-12">
          <div className="grid grid-cols-3 gap-4">
            {[
              { label: "Total Donasi", value: topDonors.reduce((a: number, d: any) => a + (d.total_donations || 0), 0), icon: TrendingUp, color: "text-[#2D7A4F]", bg: "bg-[#E8F5E9]" },
              { label: "Donor Aktif", value: topDonors.length, icon: Users, color: "text-[#1565C0]", bg: "bg-[#E3F2FD]" },
              { label: "Rating Rata-rata", value: topDonors.filter(d => d.review_count > 0).length ? (topDonors.reduce((a: number, d: any) => a + parseFloat(d.rating || "0"), 0) / topDonors.filter(d => d.review_count > 0).length).toFixed(1) : "0", icon: Star, color: "text-[#F5A623]", bg: "bg-[#FFF8E1]" },
            ].map((item, i) => (
              <motion.div key={i} initial={{ y: 10, opacity: 0 }} animate={{ y: 0, opacity: 1 }} transition={{ delay: i * 0.1 }}
                className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 text-center"
              >
                <div className={`w-12 h-12 ${item.bg} rounded-xl flex items-center justify-center mx-auto mb-2`}><item.icon size={22} className={item.color} /></div>
                <div className={`text-2xl font-bold ${item.color}`}>{item.value}</div>
                <div className="text-xs text-gray-500">{item.label}</div>
              </motion.div>
            ))}
          </div>
        </section>
      )}

      {/* Filter */}
      {!loading && topDonors.length > 0 && (
        <section className="max-w-5xl mx-auto px-6 mb-8">
          <div className="flex items-center gap-3 overflow-x-auto pb-2">
            <Filter size={16} className="text-gray-400 shrink-0" />
            {[["all", "Semua"], ["hotel", "Hotel"], ["restoran", "Restoran"], ["kafe", "Kafe"]].map(([key, label]) => (
              <button key={key} onClick={() => setFilter(key)}
                className={`px-4 py-2 rounded-full text-sm font-bold transition-all whitespace-nowrap ${filter === key ? "bg-[#F5A623] text-white shadow-sm" : "bg-white text-gray-600 border border-gray-200 hover:border-[#F5A623]"}`}
              >{label}</button>
            ))}
          </div>
        </section>
      )}

      {/* Donors Grid */}
      <section className="max-w-5xl mx-auto px-6 pb-16">
        {loading ? (
          <div className="grid md:grid-cols-3 gap-6">
            {[1,2,3].map(i => <div key={i} className="h-64 bg-white rounded-2xl skeleton-shimmer border border-gray-100" />)}
          </div>
        ) : filtered.length === 0 ? (
          <div className="text-center py-16">
            <Search size={48} className="mx-auto text-gray-300 mb-4" />
            <h3 className="text-xl font-bold text-gray-500">Belum Ada Data</h3>
            <p className="text-sm text-gray-400 mt-2">Belum ada donor yang terdaftar atau mendonasikan pangan.</p>
          </div>
        ) : (
          <div className="grid md:grid-cols-3 gap-6">
            {filtered.map((donor, idx) => (
              <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: idx * 0.08 }}
                key={idx} className="bg-white rounded-2xl p-6 text-center border border-gray-100 shadow-sm relative overflow-hidden card-hover group"
              >
                {/* Rank badge */}
                <div className={`absolute top-0 right-0 px-3 py-1 rounded-bl-xl text-white text-[10px] font-bold uppercase tracking-wider shadow-sm flex items-center gap-1 ${
                  idx === 0 ? "bg-gradient-to-r from-[#F5A623] to-[#F9A825]" :
                  idx === 1 ? "bg-gradient-to-r from-[#90A4AE] to-[#B0BEC5]" :
                  idx === 2 ? "bg-gradient-to-r from-[#A1887F] to-[#BCAAA4]" : "bg-gray-400"
                }`}>
                  {idx === 0 ? <Trophy size={12} /> : idx === 1 ? <Medal size={12} /> : idx === 2 ? <Award size={12} /> : null}
                  Rank #{idx + 1}
                </div>

                {/* Logo */}
                <div className="w-20 h-20 bg-gradient-to-br from-[#F7F4EE] to-white rounded-full mx-auto flex items-center justify-center text-3xl font-bold text-[#2D7A4F] mb-4 shadow-sm overflow-hidden border-2 border-gray-100 group-hover:border-[#F5A623] transition-all duration-300">
                  {getLogo(donor.type, donor.logo_url) ? (
                    <img src={getLogo(donor.type, donor.logo_url)} alt={donor.business_name} className="w-full h-full object-cover" />
                  ) : (
                    <Hotel size={28} className="text-gray-400" />
                  )}
                </div>

                {/* Name & type */}
                <h3 className="font-bold text-lg mb-0.5 group-hover:text-[#2D7A4F] transition-colors">{donor.business_name}</h3>
                <p className="text-xs text-gray-400 uppercase tracking-wider mb-4 flex items-center justify-center gap-1">
                  {donor.type === "hotel" ? <Hotel size={12} /> : donor.type === "restoran" ? <ShoppingBag size={12} /> : <Search size={12} />}
                  {donor.type}
                </p>

                {/* Stats */}
                <div className="flex items-center justify-center gap-4 mb-3">
                  <div className="bg-[#E8F5E9] rounded-xl py-2 px-4 inline-block font-mono font-bold text-[#2D7A4F] text-lg">
                    {donor.total_donations}
                  </div>
                  <span className="text-xs text-gray-400">donasi</span>
                </div>

                {/* Rating */}
                {donor.review_count > 0 ? (
                  <div className="flex items-center justify-center gap-1 text-[#F5A623] text-sm font-bold bg-[#FFF8E1] px-3 py-1.5 rounded-full border border-[#FFECB3] w-fit mx-auto">
                    <Star size={14} fill="currentColor" /> {donor.rating}
                    <span className="text-gray-400 font-normal">({donor.review_count} ulasan)</span>
                  </div>
                ) : (
                  <div className="flex items-center justify-center gap-1 text-gray-400 text-xs">
                    <Star size={14} /> Belum ada ulasan
                  </div>
                )}
              </motion.div>
            ))}
          </div>
        )}
      </section>

      {/* Join CTA */}
      <section className="bg-gradient-to-r from-[#F5A623] to-[#F9A825] py-16">
        <div className="max-w-3xl mx-auto px-6 text-center">
          <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}>
            <Trophy size={48} className="text-white mx-auto mb-4" />
            <h2 className="text-3xl font-bold text-white mb-4">Ingin Jadi Pahlawan Pangan?</h2>
            <p className="text-white/80 mb-8 max-w-lg mx-auto">Daftarkan bisnis Anda sekarang dan mulai berkontribusi. Setiap donasi Anda akan menginspirasi yang lain!</p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <Link to="/register/donor" className="px-6 py-3 bg-white text-[#F5A623] rounded-full font-bold hover:bg-gray-100 transition-all shadow-md flex items-center gap-2 justify-center">Daftar Donor <ArrowRight size={18} /></Link>
              <Link to="/register/recipient" className="px-6 py-3 bg-transparent text-white border-2 border-white/50 rounded-full font-bold hover:bg-white/10 transition-all flex items-center gap-2 justify-center">Daftar Penerima</Link>
            </div>
          </motion.div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-[#1a5a3e] text-white/80">
        <div className="max-w-7xl mx-auto px-6 py-12 grid grid-cols-1 md:grid-cols-4 gap-8">
          <div className="md:col-span-2">
            <div className="text-2xl font-bold tracking-tight text-white flex items-center gap-2 mb-4"><Heart className="fill-current text-[#52C77F]" /> NUTRI-SHARE</div>
            <p className="text-sm leading-relaxed max-w-sm">Platform distribusi surplus pangan berbasis Hybrid Entropy-TOPSIS — karya mahasiswa Universitas Teknologi Digital Indonesia.</p>
          </div>
          <div><h4 className="font-bold text-white mb-4">Navigasi</h4>
            <ul className="space-y-2 text-sm">
              <li><Link to="/" className="hover:text-[#52C77F] transition-colors">Beranda</Link></li>
              <li><Link to="/tentang" className="hover:text-[#52C77F] transition-colors">Tentang</Link></li>
              <li><Link to="/cara-kerja" className="hover:text-[#52C77F] transition-colors">Cara Kerja</Link></li>
              <li><Link to="/dampak" className="hover:text-[#52C77F] transition-colors">Dampak</Link></li>
              <li><Link to="/pahlawan" className="hover:text-[#52C77F] transition-colors">Pahlawan</Link></li>
            </ul>
          </div>
          <div><h4 className="font-bold text-white mb-4">Bergabung</h4>
            <ul className="space-y-2 text-sm">
              <li><Link to="/register/donor" className="hover:text-[#52C77F] transition-colors">Daftar Donor</Link></li>
              <li><Link to="/register/recipient" className="hover:text-[#52C77F] transition-colors">Daftar Penerima</Link></li>
              <li><Link to="/login" className="hover:text-[#52C77F] transition-colors">Masuk</Link></li>
            </ul>
          </div>
        </div>
        <div className="border-t border-white/10 max-w-7xl mx-auto px-6 py-4 text-sm text-white/50">© {new Date().getFullYear()} NUTRI-SHARE. Karya PKM Universitas Teknologi Digital Indonesia.</div>
      </footer>
    </div>
  );
}

