1	import { useState, useRef, useEffect, type ReactNode } from "react";
2	import { Link } from "react-router-dom";
3	import { motion, AnimatePresence } from "motion/react";
4	import { Heart, ArrowRight, Menu, X, Award, Star, Trophy, Medal, TrendingUp, Users, ShoppingBag, Hotel, Search, Quote, Filter } from "lucide-react";
5	import { api } from "../lib/api";
6	import { useHideOnScroll } from "../lib/useHideOnScroll";
7	import hotelLogo from "../assets/images/hotel_logo_1781548674916.webp";
8	import restaurantLogo from "../assets/images/restaurant_logo_1781548689113.webp";
9	import cafeLogo from "../assets/images/cafe_logo_1781548701950.webp";
10	
11	function AnimatedCounter({ target, suffix = "", className = "" }: { target: number; suffix?: string; className?: string }) {
12	  const [count, setCount] = useState(0);
13	  const ref = useRef<HTMLDivElement>(null);
14	  const done = useRef(false);
15	  useEffect(() => {
16	    const observer = new IntersectionObserver(([entry]) => {
17	      if (entry.isIntersecting && !done.current) {
18	        done.current = true;
19	        const duration = 1500, steps = 60, increment = target / steps;
20	        let current = 0;
21	        const timer = setInterval(() => { current += increment; if (current >= target) { setCount(target); clearInterval(timer); } else setCount(Math.floor(current)); }, duration / steps);
22	      }
23	    }, { threshold: 0.3 });
24	    if (ref.current) observer.observe(ref.current);
25	    return () => observer.disconnect();
26	  }, [target]);
27	  return <div ref={ref} className={`text-5xl font-bold mb-2 font-mono drop-shadow-md ${className}`}>{count}{suffix}</div>;
28	}
29	
30	export default function Heroes() {
31	  const [mobileOpen, setMobileOpen] = useState(false);
32	  const [topDonors, setTopDonors] = useState<any[]>([]);
33	  const [loading, setLoading] = useState(true);
34	  const [filter, setFilter] = useState<string>("all");
35	  const { navVisible, isScrolled } = useHideOnScroll();
36	
