38	    api.fetchJSON("/api/public/top-donors").then(data => { setTopDonors(data); setLoading(false); }).catch(() => setLoading(false));
39	  }, []);
40	
41	  const getLogo = (type: string, logoUrl?: string) => {
42	    if (logoUrl) return logoUrl;
43	    const logos: Record<string, string> = { hotel: hotelLogo, restoran: restaurantLogo, kafe: cafeLogo };
44	    return logos[type] || "";
45	  };
46	
47	  const filtered = filter === "all" ? topDonors : topDonors.filter(d => d.type === filter);
48	  const NavLink = ({ to, children }: { to: string; children: ReactNode }) => (<Link to={to} className="text-sm font-medium text-gray-600 hover:text-[#2D7A4F] transition-colors">{children}</Link>);
49	
50	  return (
51	    <div className="min-h-screen bg-[#F7F4EE] text-[#2C2C2C] font-sans">
52	      <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 transform ${navVisible ? "translate-y-0" : "-translate-y-full"} ${isScrolled ? "bg-white/90 backdrop-blur-lg shadow-sm" : "bg-transparent"}`}>
53	        <div className="max-w-7xl mx-auto flex items-center justify-between px-6 py-4">
54	          <Link to="/" className="text-2xl font-bold tracking-tight text-[#2D7A4F] flex items-center gap-2"><Heart className="fill-current text-[#52C77F]" />NUTRI-SHARE</Link>
55	          <div className="hidden md:flex items-center gap-6">
56	            <NavLink to="/">Beranda</NavLink>
57	            <NavLink to="/tentang">Tentang</NavLink>
58	            <NavLink to="/cara-kerja">Cara Kerja</NavLink>
59	            <NavLink to="/dampak">Dampak</NavLink>
