257	  if (db) db.close();
258	  const resolved = dbPath || process.env.DB_PATH || path.join(process.cwd(), "data", "nutrishare.db");
259	  if (process.env.DB_PATH) logger.info(`Using DB_PATH: ${resolved}`);
260	  db = new BetterSqlite3(resolved);
261	  db.pragma("journal_mode = WAL");
262	  db.pragma("foreign_keys = ON");
263	  db.pragma("busy_timeout = 5000");
264	  db.pragma("synchronous = NORMAL");
265	  db.exec(SCHEMA);
266	  return db;
267	}
268	
269	export function getDb(): Database {
270	  return db;
271	}
272	
273	export function resetDb(): void {
274	  db.exec(`
275	    DELETE FROM reviews;
276	    DELETE FROM notifications;
277	    DELETE FROM claims;
278	    DELETE FROM topsis_results;
279	    DELETE FROM donations;
280	    DELETE FROM recipient_profiles;
281	    DELETE FROM donor_profiles;
282	    DELETE FROM users;
283	  `);
284	}
285	
286	export function closeDb(): void {
287	  if (db) db.close();
288	}
289	
290	// Default: init with file-based DB (called by server.ts)
291	// For tests, call initDb(":memory:") before importing routes
292	
293	// Proxy for backward compatibility — lets `db.prepare()` work even if initDb() is called later
294	const dbProxy = new Proxy({} as any, {
295	  get: (_, prop) => {
296	    if (!db) throw new Error("Database not initialized. Call initDb() first.");
297	    return (db as any)[prop];
298	  },
299	});
300	
301	export default dbProxy;
