1	import { Router, Response } from "express";
2	import bcrypt from "bcryptjs";
3	import db from "./db.js";
4	import { AuthRequest, authMiddleware, requireRole, signToken, setAuthCookie, clearAuthCookie } from "./auth.js";
5	import { runTopsisAllActive, calculateTopsisForDonation } from "./topsis.js";
6	import { validate, loginSchema, registerDonorSchema, registerRecipientSchema, registerAdminSchema, createDonationSchema, claimDonationSchema, reviewSchema, adminVerifySchema, emergencySchema } from "./validate.js";
7	
8	export const apiRouter = Router();
9	
10	// --- Activity Logger ---
11	function logActivity(userId: number, action: string, details?: string) {
12	  try {
13	    db.prepare("INSERT INTO activity_logs (user_id, action, details, created_at) VALUES (?, ?, ?, ?)").run(userId, action, details || "", new Date().toISOString());
14	  } catch {}
15	}
16	
17	// --- Auth ---
18	apiRouter.post("/auth/register/admin", validate(registerAdminSchema), async (req: AuthRequest, res: Response): Promise<void> => {
19	  const adminKey = process.env.ADMIN_SECRET_KEY || (process.env.NODE_ENV === "production" ? (() => { throw new Error("ADMIN_SECRET_KEY environment variable is required in production"); })() : "admin-secret-change-me");
20	  if (req.body.admin_key !== adminKey) {
21	    res.status(403).json({ message: "Kunci admin tidak valid" });
22	    return;
23	  }
24	  const { name, email, password } = req.body;
25	  if (!name || !email || !password) {
26	    res.status(400).json({ message: "Nama, email, dan password wajib diisi" });
27	    return;
28	  }
29	  const existing = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
30	  if (existing) {
31	    res.status(409).json({ message: "Email sudah terdaftar" });
32	    return;
33	  }
34	  const hash = await bcrypt.hash(password, 10);
35	  const result = db.prepare("INSERT INTO users (name, email, password, role, status) VALUES (?, ?, ?, 'admin', 'verified')").run(name, email, hash);
36	  const user = db.prepare("SELECT id, name, email, role, status FROM users WHERE id = ?").get(result.lastInsertRowid) as any;
37	  res.json({ message: "Admin berhasil dibuat", user });
38	});
39	
40	apiRouter.post("/auth/login", validate(loginSchema), async (req: AuthRequest, res: Response): Promise<void> => {
41	  const { email, password } = req.body;
42	  const user = db.prepare("SELECT * FROM users WHERE email = ?").get(email) as any;
43	  if (!user || !(await bcrypt.compare(password, user.password))) {
44	    res.status(401).json({ message: "Kredensial tidak valid" });
45	    return;
46	  }
47	  if (user.status !== "verified" && user.role !== "admin") {
48	    res.status(403).json({ message: "Akun Anda belum diverifikasi admin." });
49	    return;
50	  }
51	  let profile = null;
52	  if (user.role === "donor") profile = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(user.id);
53	  if (user.role === "recipient") profile = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(user.id);
54	
55	  const token = signToken(user);
56	  setAuthCookie(res, token);
57	
58	  logActivity(user.id, "login", `User ${user.role} login`);
59	
60	  const { password: _, ...safeUser } = user;
61	  res.json({ user: safeUser, profile });
62	});
63	
64	// --- Forgot / Reset Password ---
65	apiRouter.post("/auth/forgot-password", async (req: AuthRequest, res: Response): Promise<void> => {
66	  const { email } = req.body;
67	  if (!email) { res.status(400).json({ message: "Email wajib diisi" }); return; }
68	  const user = db.prepare("SELECT id FROM users WHERE email = ?").get(email) as any;
69	  if (!user) { res.status(404).json({ message: "Email tidak terdaftar" }); return; }
70	  const resetToken = [...Array(32)].map(() => Math.random().toString(36)[2]).join("");
71	  const expiry = new Date(Date.now() + 3600000).toISOString();
72	  db.prepare("UPDATE users SET reset_token = ?, reset_token_expiry = ? WHERE id = ?").run(resetToken, expiry, user.id);
73	  // In production, send email with reset link. For demo, return the token.
74	  res.json({ message: "Link reset password telah dikirim", resetToken: process.env.NODE_ENV === "production" ? undefined : resetToken });
75	});
76	
77	apiRouter.post("/auth/reset-password", async (req: AuthRequest, res: Response): Promise<void> => {
78	  const { token, password } = req.body;
79	  if (!token || !password) { res.status(400).json({ message: "Token dan password baru wajib diisi" }); return; }
80	  if (password.length < 6) { res.status(400).json({ message: "Password minimal 6 karakter" }); return; }
81	  const user = db.prepare("SELECT id FROM users WHERE reset_token = ? AND reset_token_expiry > ?").get(token, new Date().toISOString()) as any;
82	  if (!user) { res.status(400).json({ message: "Token tidak valid atau sudah kedaluwarsa" }); return; }
83	  const hash = await bcrypt.hash(password, 10);
84	  db.prepare("UPDATE users SET password = ?, reset_token = NULL, reset_token_expiry = NULL WHERE id = ?").run(hash, user.id);
85	  res.json({ message: "Password berhasil direset. Silakan login." });
86	});
87	
88	apiRouter.post("/auth/logout", (_req: AuthRequest, res: Response) => {
89	  clearAuthCookie(res);
90	  res.json({ message: "Logout berhasil" });
91	});
92	
93	apiRouter.get("/auth/me", authMiddleware, (req: AuthRequest, res: Response) => {
94	  const user = db.prepare("SELECT id, name, email, role, status FROM users WHERE id = ?").get(req.user!.id) as any;
95	  if (!user) { clearAuthCookie(res); res.status(401).json({ message: "User tidak ditemukan" }); return; }
96	  let profile = null;
97	  if (user.role === "donor") profile = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(user.id);
98	  if (user.role === "recipient") profile = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(user.id);
99	  res.json({ user, profile });
100	});
101	
102	// --- Registration ---
103	apiRouter.post("/auth/register/donor", validate(registerDonorSchema), async (req: AuthRequest, res: Response): Promise<void> => {
104	  const { business_name, email, password, business_type, address, latitude, longitude, phone } = req.body;
105	  const existing = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
106	  if (existing) { res.status(409).json({ message: "Email sudah terdaftar" }); return; }
107	  const hash = await bcrypt.hash(password, 10);
108	  const uResult = db.prepare("INSERT INTO users (name, email, password, role, status) VALUES (?, ?, ?, 'donor', 'pending')").run(business_name, email, hash);
109	  const userId = uResult.lastInsertRowid as number;
110	  db.prepare("INSERT INTO donor_profiles (user_id, business_name, business_type, address, latitude, longitude, phone) VALUES (?, ?, ?, ?, ?, ?, ?)")
111	    .run(userId, business_name, business_type, address, parseFloat(latitude), parseFloat(longitude), phone);
112	  res.json({ message: "Berhasil daftar. Menunggu verifikasi admin." });
113	});
114	
115	apiRouter.post("/auth/register/recipient", validate(registerRecipientSchema), async (req: AuthRequest, res: Response): Promise<void> => {
116	  const { institution_name, email, password, institution_type, address, latitude, longitude, phone, resident_count, age_range, health_condition, daily_protein_need, daily_calorie_need, daily_iron_need, daily_vitamin_c_need } = req.body;
117	  const existing = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
118	  if (existing) { res.status(409).json({ message: "Email sudah terdaftar" }); return; }
119	  const hash = await bcrypt.hash(password, 10);
120	  const uResult = db.prepare("INSERT INTO users (name, email, password, role, status) VALUES (?, ?, ?, 'recipient', 'pending')").run(institution_name, email, hash);
121	  const userId = uResult.lastInsertRowid as number;
122	  db.prepare(`INSERT INTO recipient_profiles (user_id, institution_name, institution_type, address, latitude, longitude, phone, resident_count, age_range, health_condition, daily_protein_need, daily_calorie_need, daily_iron_need, daily_vitamin_c_need) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
123	    .run(userId, institution_name, institution_type, address, parseFloat(latitude), parseFloat(longitude), phone, parseInt(resident_count), age_range, health_condition, parseFloat(daily_protein_need), parseFloat(daily_calorie_need), parseFloat(daily_iron_need), parseFloat(daily_vitamin_c_need));
124	  res.json({ message: "Berhasil daftar. Menunggu verifikasi admin." });
125	});
126	
127	// --- Profile ---
128	apiRouter.put("/users/:id/profile", authMiddleware, async (req: AuthRequest, res: Response): Promise<void> => {
129	  const userId = parseInt(req.params.id);
130	  const user = db.prepare("SELECT * FROM users WHERE id = ?").get(userId) as any;
131	  if (!user) { res.status(404).json({ message: "User tidak ditemukan" }); return; }
132	  const d = req.body;
133	  if (d.name) db.prepare("UPDATE users SET name = ? WHERE id = ?").run(d.name, userId);
134	  if (d.email) db.prepare("UPDATE users SET email = ? WHERE id = ?").run(d.email, userId);
135	  if (d.password) db.prepare("UPDATE users SET password = ? WHERE id = ?").run(await bcrypt.hash(d.password, 10), userId);
136	
137	  if (user.role === "donor") {
138	    const p = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(userId);
139	    if (p) {
140	      if (d.business_name) db.prepare("UPDATE donor_profiles SET business_name = ? WHERE user_id = ?").run(d.business_name, userId);
141	      if (d.business_type) db.prepare("UPDATE donor_profiles SET business_type = ? WHERE user_id = ?").run(d.business_type, userId);
142	      if (d.address) db.prepare("UPDATE donor_profiles SET address = ? WHERE user_id = ?").run(d.address, userId);
143	      if (d.latitude) db.prepare("UPDATE donor_profiles SET latitude = ? WHERE user_id = ?").run(parseFloat(d.latitude), userId);
144	      if (d.longitude) db.prepare("UPDATE donor_profiles SET longitude = ? WHERE user_id = ?").run(parseFloat(d.longitude), userId);
145	      if (d.phone) db.prepare("UPDATE donor_profiles SET phone = ? WHERE user_id = ?").run(d.phone, userId);
146	      if (d.logo_url !== undefined) db.prepare("UPDATE donor_profiles SET logo_url = ? WHERE user_id = ?").run(d.logo_url, userId);
147	    }
148	  } else if (user.role === "recipient") {
149	    const p = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(userId);
150	    if (p) {
151	      if (d.institution_name) db.prepare("UPDATE recipient_profiles SET institution_name = ? WHERE user_id = ?").run(d.institution_name, userId);
152	      if (d.institution_type) db.prepare("UPDATE recipient_profiles SET institution_type = ? WHERE user_id = ?").run(d.institution_type, userId);
153	      if (d.address) db.prepare("UPDATE recipient_profiles SET address = ? WHERE user_id = ?").run(d.address, userId);
154	      if (d.latitude) db.prepare("UPDATE recipient_profiles SET latitude = ? WHERE user_id = ?").run(parseFloat(d.latitude), userId);
155	      if (d.longitude) db.prepare("UPDATE recipient_profiles SET longitude = ? WHERE user_id = ?").run(parseFloat(d.longitude), userId);
156	      if (d.phone) db.prepare("UPDATE recipient_profiles SET phone = ? WHERE user_id = ?").run(d.phone, userId);
157	      if (d.logo_url !== undefined) db.prepare("UPDATE recipient_profiles SET document_url = ? WHERE user_id = ?").run(d.logo_url, userId);
158	      if (d.resident_count) db.prepare("UPDATE recipient_profiles SET resident_count = ? WHERE user_id = ?").run(parseInt(d.resident_count), userId);
159	      if (d.daily_protein_need) db.prepare("UPDATE recipient_profiles SET daily_protein_need = ? WHERE user_id = ?").run(parseFloat(d.daily_protein_need), userId);
160	      if (d.daily_calorie_need) db.prepare("UPDATE recipient_profiles SET daily_calorie_need = ? WHERE user_id = ?").run(parseFloat(d.daily_calorie_need), userId);
161	      if (d.daily_iron_need) db.prepare("UPDATE recipient_profiles SET daily_iron_need = ? WHERE user_id = ?").run(parseFloat(d.daily_iron_need), userId);
162	      if (d.daily_vitamin_c_need) db.prepare("UPDATE recipient_profiles SET daily_vitamin_c_need = ? WHERE user_id = ?").run(parseFloat(d.daily_vitamin_c_need), userId);
163	    }
164	  }
165	  const updated = db.prepare("SELECT id, name, email, role, status FROM users WHERE id = ?").get(userId) as any;
166	  let profile = null;
167	  if (user.role === "donor") profile = db.prepare("SELECT * FROM donor_profiles WHERE user_id = ?").get(userId);
168	  if (user.role === "recipient") profile = db.prepare("SELECT * FROM recipient_profiles WHERE user_id = ?").get(userId);
169	  res.json({ message: "Profil berhasil diperbarui", user: updated, profile });
170	});
171	
172	// --- Public Data ---
173	apiRouter.get("/public/top-donors", (_req: AuthRequest, res: Response) => {
174	  const donors = db.prepare("SELECT * FROM donor_profiles ORDER BY total_donations DESC LIMIT 3").all() as any[];
175	  const result = donors.map((p: any) => {
176	    const reviews = db.prepare("SELECT rating FROM reviews WHERE donor_id = ?").all(p.user_id) as any[];
177	    const avgRating = reviews.length > 0 ? reviews.reduce((sum: number, r: any) => sum + r.rating, 0) / reviews.length : 0;
178	    return {
179	      id: p.user_id, business_name: p.business_name, total_donations: p.total_donations,
180	      type: p.business_type, logo_url: p.logo_url,
181	      rating: avgRating.toFixed(1), review_count: reviews.length
182	    };
183	  });
184	  res.json(result);
185	});
186	
187	// --- Dashboard Stats ---
188	apiRouter.get("/dashboard/stats", (_req: AuthRequest, res: Response) => {
189	  const donors = (db.prepare("SELECT COUNT(*) as c FROM users WHERE role = 'donor'").get() as any).c;
190	  const recipients = (db.prepare("SELECT COUNT(*) as c FROM users WHERE role = 'recipient'").get() as any).c;
191	  const active = (db.prepare("SELECT COUNT(*) as c FROM donations WHERE status = 'active'").get() as any).c;
192	  const completed = (db.prepare("SELECT COUNT(*) as c FROM donations WHERE status = 'completed'").get() as any).c;
193	  res.json({ donors, recipients, active_donations: active, completed_donations: completed });
194	});
195	
196	// --- Trend Stats ---
197	apiRouter.get("/dashboard/trends", (_req: AuthRequest, res: Response) => {
198	  // Last 7 days donation completions
199	  const weekly: { date: string; count: number }[] = [];
200	  for (let i = 6; i >= 0; i--) {
201	    const d = new Date(); d.setDate(d.getDate() - i);
202	    const dayStart = new Date(d); dayStart.setHours(0, 0, 0, 0);
203	    const dayEnd = new Date(d); dayEnd.setHours(23, 59, 59, 999);
204	    const count = (db.prepare("SELECT COUNT(*) as c FROM donations WHERE completed_at >= ? AND completed_at <= ?").get(dayStart.toISOString(), dayEnd.toISOString()) as any).c;
205	    weekly.push({ date: dayStart.toISOString().slice(0, 10), count });
206	  }
207	  // Top food types donated
208	  const foodTypes = db.prepare("SELECT food_type, COUNT(*) as c FROM donations GROUP BY food_type ORDER BY c DESC").all() as any[];
209	  // Total portions donated
210	  const totalPortions = (db.prepare("SELECT COALESCE(SUM(portion_count), 0) as t FROM donations WHERE status = 'completed'").get() as any).t;
211	  // Total protein distributed
212	  const totalProtein = (db.prepare("SELECT COALESCE(SUM(protein_per_portion * portion_count), 0) as t FROM donations WHERE status = 'completed'").get() as any).t;
